const o={"ko-first-u01.title":"Zwierzęta","ko-first-u01.tip":"Popatrzcie na obrazek, posłuchajcie i powiedzcie razem koreańskie słowo. Nic nie szkodzi, jeśli dziecko jeszcze nie umie czytać.","ko-first-u01.w.0":"kot","ko-first-u01.w.1":"piesek","ko-first-u01.w.2":"ryba","ko-first-u01.w.3":"ptak","ko-first-u01.w.4":"krowa","ko-first-u01.w.5":"świnka","ko-first-u02.title":"Coś do jedzenia","ko-first-u02.tip":"Popatrzcie na obrazek, posłuchajcie i powiedzcie razem koreańskie słowo. Nic nie szkodzi, jeśli dziecko jeszcze nie umie czytać.","ko-first-u02.w.0":"jabłko","ko-first-u02.w.1":"banan","ko-first-u02.w.2":"mleko","ko-first-u02.w.3":"chleb","ko-first-u02.w.4":"jajko","ko-first-u02.w.5":"ryż","ko-first-u03.title":"Zabawki","ko-first-u03.tip":"Popatrzcie na obrazek, posłuchajcie i powiedzcie razem koreańskie słowo. Nic nie szkodzi, jeśli dziecko jeszcze nie umie czytać.","ko-first-u03.w.0":"piłka","ko-first-u03.w.1":"samochód","ko-first-u03.w.2":"miś","ko-first-u03.w.3":"latawiec","ko-first-u03.w.4":"pociąg","ko-first-u03.w.5":"łódka","ko-first-u04.title":"Ciało","ko-first-u04.tip":"Popatrzcie na obrazek, posłuchajcie i powiedzcie razem koreańskie słowo. Nic nie szkodzi, jeśli dziecko jeszcze nie umie czytać.","ko-first-u04.w.0":"oko","ko-first-u04.w.1":"ucho","ko-first-u04.w.2":"nos","ko-first-u04.w.3":"usta","ko-first-u04.w.4":"ręka","ko-first-u04.w.5":"stopa","ko-first-u05.title":"Kolory","ko-first-u05.tip":"Popatrzcie na obrazek, posłuchajcie i powiedzcie razem koreańskie słowo. Nic nie szkodzi, jeśli dziecko jeszcze nie umie czytać.","ko-first-u05.w.0":"czerwony","ko-first-u05.w.1":"niebieski","ko-first-u05.w.2":"żółty","ko-first-u05.w.3":"zielony","ko-first-u05.w.4":"czarny","ko-first-u05.w.5":"biały","ko-first-u06.title":"Rodzina","ko-first-u06.tip":"Popatrzcie na obrazek, posłuchajcie i powiedzcie razem koreańskie słowo. Nic nie szkodzi, jeśli dziecko jeszcze nie umie czytać.","ko-first-u06.w.0":"mama","ko-first-u06.w.1":"tata","ko-first-u06.w.2":"dzidziuś","ko-first-u06.w.3":"babcia","ko-first-u06.w.4":"dziadek","ko-first-u06.w.5":"dziecko","ko-first-u07.title":"W domu","ko-first-u07.tip":"Popatrzcie na obrazek, posłuchajcie i powiedzcie razem koreańskie słowo. Nic nie szkodzi, jeśli dziecko jeszcze nie umie czytać.","ko-first-u07.w.0":"dom","ko-first-u07.w.1":"łóżko","ko-first-u07.w.2":"krzesło","ko-first-u07.w.3":"drzwi","ko-first-u07.w.4":"książka","ko-first-u07.w.5":"kubek","ko-first-u08.title":"Na dworze","ko-first-u08.tip":"Popatrzcie na obrazek, posłuchajcie i powiedzcie razem koreańskie słowo. Nic nie szkodzi, jeśli dziecko jeszcze nie umie czytać.","ko-first-u08.w.0":"słońce","ko-first-u08.w.1":"księżyc","ko-first-u08.w.2":"gwiazda","ko-first-u08.w.3":"drzewo","ko-first-u08.w.4":"kwiat","ko-first-u08.w.5":"deszcz"},i={"ko-kinder-u01.title":"Samogłoski ㅏ ㅓ ㅗ ㅜ ㅣ","ko-kinder-u01.tip":"Koreańskie litery łączą się w bloki. ㅇ na początku jest nieme, więc 아 brzmi po prostu jak „a”. Powiedz 아, 어, 오, 우, 이, szeroko otwierając buzię!","ko-kinder-u01.w.0":"dzidziuś","ko-kinder-u01.w.1":"lody","ko-kinder-u01.w.2":"mama","ko-kinder-u01.w.3":"kaczka","ko-kinder-u01.w.4":"ogórek","ko-kinder-u01.w.5":"mleko","ko-kinder-u01.w.6":"parasol","ko-kinder-u01.w.7":"ząb","ko-kinder-u01.s.0":"Dzidziuś śpi.","ko-kinder-u01.s.1":"Idzie kaczka.","ko-kinder-u01.s.2":"Poproszę mleko.","ko-kinder-u02.title":"Litery ㄱ ㄴ ㄷ","ko-kinder-u02.tip":"Blok to spółgłoska i samogłoska: ㄱ + ㅏ = 가. Dotknij każdej karty, żeby usłyszeć nazwę litery, a potem przeczytajcie blok razem.","ko-kinder-u02.w.0":"torba","ko-kinder-u02.w.1":"mięso","ko-kinder-u02.w.2":"buty","ko-kinder-u02.w.3":"motyl","ko-kinder-u02.w.4":"drzewo","ko-kinder-u02.w.5":"piosenka","ko-kinder-u02.w.6":"wiewiórka","ko-kinder-u02.w.7":"żołądź","ko-kinder-u02.s.0":"Motyl lata.","ko-kinder-u02.s.1":"Torba jest duża.","ko-kinder-u02.s.2":"Wiewiórka je.","ko-kinder-u03.title":"Litery ㄹ ㅁ ㅂ","ko-kinder-u03.tip":"ㄹ brzmi jak coś pomiędzy „r” a „l”. ㅁ wygląda jak zamknięta buzia — i żeby go powiedzieć, zamykasz usta!","ko-kinder-u03.w.0":"ramen","ko-kinder-u03.w.1":"cytryna","ko-kinder-u03.w.2":"koń","ko-kinder-u03.w.3":"kapelusz","ko-kinder-u03.w.4":"tęcza","ko-kinder-u03.w.5":"banan","ko-kinder-u03.w.6":"autobus","ko-kinder-u03.w.7":"deszcz","ko-kinder-u03.s.0":"Kapelusz jest ładny.","ko-kinder-u03.s.1":"Jedzie autobus.","ko-kinder-u03.s.2":"Pada deszcz.","ko-kinder-u04.title":"Litery ㅅ ㅇ ㅈ","ko-kinder-u04.tip":"ㅇ na początku bloku jest nieme (아, 오), ale na dole brzmi jak „ng” (방). ㅅ wygląda jak mały namiot: 사, 소.","ko-kinder-u04.w.0":"lew","ko-kinder-u04.w.1":"jabłko","ko-kinder-u04.w.2":"krowa","ko-kinder-u04.w.3":"arbuz","ko-kinder-u04.w.4":"zegar","ko-kinder-u04.w.5":"samochód","ko-kinder-u04.w.6":"sok","ko-kinder-u04.w.7":"Ziemia","ko-kinder-u04.s.0":"Lew jest duży.","ko-kinder-u04.s.1":"Poproszę sok.","ko-kinder-u04.s.2":"Arbuz jest pyszny.","ko-kinder-u05.title":"Litery ㅊ ㅋ ㅌ","ko-kinder-u05.tip":"ㅊ, ㅋ, ㅌ to litery „z dmuchnięciem”: ㅋ to ㄱ z dodatkową kreską i dodatkowym podmuchem powietrza. Przyłóż rękę do buzi i poczuj to!","ko-kinder-u05.w.0":"spódnica","ko-kinder-u05.w.1":"ser","ko-kinder-u05.w.2":"nos","ko-kinder-u05.w.3":"słoń","ko-kinder-u05.w.4":"ciastko","ko-kinder-u05.w.5":"królik","ko-kinder-u05.w.6":"pomidor","ko-kinder-u05.w.7":"ciężarówka","ko-kinder-u05.s.0":"Królik skacze.","ko-kinder-u05.s.1":"Słoń ma długą trąbę.","ko-kinder-u05.s.2":"Poproszę ciastko.","ko-kinder-u06.title":"Litery ㅍ ㅎ","ko-kinder-u06.tip":"ㅎ brzmi jak „h” — 하, 호, 후, jak cichy śmiech. Teraz znasz wszystkie 14 podstawowych spółgłosek!","ko-kinder-u06.w.0":"winogrona","ko-kinder-u06.w.1":"pizza","ko-kinder-u06.w.2":"fala","ko-kinder-u06.w.3":"pingwin","ko-kinder-u06.w.4":"hipopotam","ko-kinder-u06.w.5":"słońce","ko-kinder-u06.w.6":"tygrys","ko-kinder-u06.w.7":"chusteczka","ko-kinder-u06.s.0":"Pingwin idzie.","ko-kinder-u06.s.1":"Tygrys śpi.","ko-kinder-u06.s.2":"Winogrona są pyszne.","ko-kinder-u07.title":"Samogłoski ㅑ ㅕ ㅛ ㅠ ㅐ ㅔ","ko-kinder-u07.tip":"Dodatkowa kreska dodaje „j”: ㅏ (a) → ㅑ (ja), ㅗ (o) → ㅛ (jo). ㅐ i ㅔ brzmią dziś prawie tak samo — nawet Koreańczycy je mylą!","ko-kinder-u07.w.0":"baseball","ko-kinder-u07.w.1":"lis","ko-kinder-u07.w.2":"gotowanie","ko-kinder-u07.w.3":"duch","ko-kinder-u07.w.4":"gąsienica","ko-kinder-u07.w.5":"pies","ko-kinder-u07.w.6":"gruszka","ko-kinder-u07.w.7":"krab","ko-kinder-u07.s.0":"Lis się uśmiecha.","ko-kinder-u07.s.1":"Krab idzie.","ko-kinder-u07.s.2":"Gotuję.","ko-kinder-u08.title":"Litery na dole (batchim)","ko-kinder-u08.tip":"Spółgłoska może siedzieć na dole bloku: ㄱ + ㅗ + ㅁ = 곰. Ta dolna litera nazywa się batchim (받침). Teraz umiesz przeczytać prawie każde koreańskie słowo!","ko-kinder-u08.w.0":"niedźwiedź","ko-kinder-u08.w.1":"piłka","ko-kinder-u08.w.2":"śnieg","ko-kinder-u08.w.3":"góra","ko-kinder-u08.w.4":"chleb","ko-kinder-u08.w.5":"gwiazda","ko-kinder-u08.w.6":"księżyc","ko-kinder-u08.w.7":"woda","ko-kinder-u08.s.0":"Niedźwiedź śpi.","ko-kinder-u08.s.1":"Pada śnieg.","ko-kinder-u08.s.2":"Poproszę wodę."},k={"ko-g12-u01.title":"Powitania","ko-g12-u01.tip":"Kiedy mówisz 안녕하세요, lekko się ukłoń — tak witają się Koreańczycy. Z bliskimi przyjaciółmi możesz powiedzieć po prostu 안녕!","ko-g12-u01.w.0":"dzień dobry","ko-g12-u01.w.1":"do widzenia (do kogoś, kto wychodzi)","ko-g12-u01.w.2":"dziękuję","ko-g12-u01.w.3":"przepraszam","ko-g12-u01.w.4":"tak","ko-g12-u01.w.5":"nie","ko-g12-u01.w.6":"przyjaciel","ko-g12-u01.w.7":"nauczyciel","ko-g12-u01.w.8":"dobranoc","ko-g12-u01.s.0":"Dzień dobry, proszę pani.","ko-g12-u01.s.1":"Tak, dziękuję.","ko-g12-u01.s.2":"Nie, nic się nie stało.","ko-g12-u01.s.3":"Bardzo przepraszam.","ko-g12-u01.s.4":"Cześć, przyjacielu!","ko-g12-u01.s.5":"Dobranoc, mamo.","ko-g12-u02.title":"Liczby 1–10","ko-g12-u02.tip":"W koreańskim są dwa zestawy liczb. 하나, 둘, 셋 służą do liczenia rzeczy i mówienia, ile masz lat. Policz nimi swoje palce!","ko-g12-u02.w.0":"jeden","ko-g12-u02.w.1":"dwa","ko-g12-u02.w.2":"trzy","ko-g12-u02.w.3":"cztery","ko-g12-u02.w.4":"pięć","ko-g12-u02.w.5":"sześć","ko-g12-u02.w.6":"siedem","ko-g12-u02.w.7":"osiem","ko-g12-u02.w.8":"dziewięć","ko-g12-u02.w.9":"dziesięć","ko-g12-u02.s.0":"Raz, dwa, trzy!","ko-g12-u02.s.1":"Cztery, pięć, sześć.","ko-g12-u02.s.2":"Siedem, osiem, dziewięć, dziesięć.","ko-g12-u02.s.3":"Mam pięć lat.","ko-g12-u02.s.4":"Mam dziesięć palców.","ko-g12-u02.s.5":"Jeszcze jeden, proszę.","ko-g12-u03.title":"Kolory","ko-g12-u03.tip":"Każda nazwa koloru kończy się na 색 (kolor). Pokazuj rzeczy dookoła i mów, jakiego są koloru: 빨간색!","ko-g12-u03.w.0":"czerwony","ko-g12-u03.w.1":"niebieski","ko-g12-u03.w.2":"żółty","ko-g12-u03.w.3":"zielony","ko-g12-u03.w.4":"fioletowy","ko-g12-u03.w.5":"pomarańczowy","ko-g12-u03.w.6":"różowy","ko-g12-u03.w.7":"czarny","ko-g12-u03.w.8":"biały","ko-g12-u03.s.0":"Jabłka są czerwone.","ko-g12-u03.s.1":"Niebo jest niebieskie.","ko-g12-u03.s.2":"Banany są żółte.","ko-g12-u03.s.3":"Liście są zielone.","ko-g12-u03.s.4":"Winogrona są fioletowe.","ko-g12-u03.s.5":"Lubię różowy.","ko-g12-u04.title":"Rodzina","ko-g12-u04.tip":"O rodzinie i domu Koreańczycy mówią 우리 (nasz) zamiast „mój”: 우리 엄마, 우리 집. Brzmi to ciepło i przyjaźnie.","ko-g12-u04.w.0":"rodzina","ko-g12-u04.w.1":"mama","ko-g12-u04.w.2":"tata","ko-g12-u04.w.3":"babcia","ko-g12-u04.w.4":"dziadek","ko-g12-u04.w.5":"młodszy brat lub siostra","ko-g12-u04.w.6":"dzidziuś","ko-g12-u04.w.7":"piesek","ko-g12-u04.s.0":"To moja rodzina.","ko-g12-u04.s.1":"Mamo, kocham cię.","ko-g12-u04.s.2":"Tata jest wysoki.","ko-g12-u04.s.3":"Babcia się uśmiecha.","ko-g12-u04.s.4":"Mój młodszy brat płacze.","ko-g12-u04.s.5":"Piesek też jest częścią rodziny.","ko-g12-u05.title":"Zwierzęta","ko-g12-u05.tip":"Koreańskie odgłosy zwierząt są zabawne: kot robi 야옹, pies robi 멍멍, a żaba robi 개굴개굴. Spróbuj!","ko-g12-u05.w.0":"kot","ko-g12-u05.w.1":"małpa","ko-g12-u05.w.2":"żyrafa","ko-g12-u05.w.3":"mysz","ko-g12-u05.w.4":"wąż","ko-g12-u05.w.5":"kura","ko-g12-u05.w.6":"owca","ko-g12-u05.w.7":"żółw","ko-g12-u05.w.8":"żaba","ko-g12-u05.s.0":"Kot robi miau.","ko-g12-u05.s.1":"Żyrafy mają długie szyje.","ko-g12-u05.s.2":"Małpa je banana.","ko-g12-u05.s.3":"Żółwie są powolne.","ko-g12-u05.s.4":"Żaba skacze.","ko-g12-u05.s.5":"Owca je trawę.","ko-g12-u06.title":"Owoce","ko-g12-u06.tip":"배 to gruszka — ale też statek i brzuch! Obrazek podpowie ci, o które chodzi.","ko-g12-u06.w.0":"jabłko","ko-g12-u06.w.1":"banan","ko-g12-u06.w.2":"truskawka","ko-g12-u06.w.3":"winogrona","ko-g12-u06.w.4":"arbuz","ko-g12-u06.w.5":"mandarynka","ko-g12-u06.w.6":"brzoskwinia","ko-g12-u06.w.7":"gruszka","ko-g12-u06.w.8":"kiwi","ko-g12-u06.s.0":"Truskawka jest czerwona.","ko-g12-u06.s.1":"Mandarynka jest słodka.","ko-g12-u06.s.2":"Lubię brzoskwinie.","ko-g12-u06.s.3":"Arbuz jest naprawdę duży.","ko-g12-u06.s.4":"Poproszę winogrona.","ko-g12-u06.s.5":"Kiwi są zielone.","ko-g12-u07.title":"Jedzenie","ko-g12-u07.tip":"Przed jedzeniem Koreańczycy mówią 잘 먹겠습니다 (będę dobrze jeść), a po jedzeniu 잘 먹었습니다. Spróbuj przy następnym posiłku!","ko-g12-u07.w.0":"ryż","ko-g12-u07.w.1":"kimchi","ko-g12-u07.w.2":"zupa","ko-g12-u07.w.3":"gimbap (rolka ryżowa)","ko-g12-u07.w.4":"ciastko ryżowe","ko-g12-u07.w.5":"pieróg","ko-g12-u07.w.6":"jajko","ko-g12-u07.w.7":"ryba (do jedzenia)","ko-g12-u07.w.8":"łyżka","ko-g12-u07.w.9":"pałeczki","ko-g12-u07.s.0":"Jem ryż.","ko-g12-u07.s.1":"Kimchi jest ostre.","ko-g12-u07.s.2":"Pierogi są pyszne.","ko-g12-u07.s.3":"Zupa jest gorąca.","ko-g12-u07.s.4":"Jem pałeczkami.","ko-g12-u07.s.5":"Poproszę gimbap.","ko-g12-u07.s.6":"Jestem głodny.","ko-g12-u08.title":"Ciało","ko-g12-u08.tip":"Zagraj po koreańsku w „Szymon mówi”: 코! 귀! 머리! Dotknij każdej części ciała, kiedy ją usłyszysz.","ko-g12-u08.w.0":"głowa","ko-g12-u08.w.1":"oko","ko-g12-u08.w.2":"nos","ko-g12-u08.w.3":"usta","ko-g12-u08.w.4":"ucho","ko-g12-u08.w.5":"ręka","ko-g12-u08.w.6":"stopa","ko-g12-u08.w.7":"noga","ko-g12-u08.w.8":"ramię","ko-g12-u08.s.0":"Mam dwoje oczu.","ko-g12-u08.s.1":"Dotknij nosa.","ko-g12-u08.s.2":"Myję ręce.","ko-g12-u08.s.3":"Otwórz szeroko buzię.","ko-g12-u08.s.4":"Boli mnie głowa.","ko-g12-u08.s.5":"Mam długie nogi.","ko-g12-u09.title":"Szkoła","ko-g12-u09.tip":"W Korei uczniowie mówią do nauczyciela 선생님 — nigdy po imieniu. 님 to grzeczna końcówka, która okazuje szacunek.","ko-g12-u09.w.0":"szkoła","ko-g12-u09.w.1":"klasa","ko-g12-u09.w.2":"ołówek","ko-g12-u09.w.3":"gumka","ko-g12-u09.w.4":"zeszyt","ko-g12-u09.w.5":"nożyczki","ko-g12-u09.w.6":"ławka","ko-g12-u09.w.7":"tablica","ko-g12-u09.w.8":"praca domowa","ko-g12-u09.s.0":"Idę do szkoły.","ko-g12-u09.s.1":"Mam ołówek.","ko-g12-u09.s.2":"Pożycz mi gumkę, proszę.","ko-g12-u09.s.3":"Piszę w zeszycie.","ko-g12-u09.s.4":"Mam dużo pracy domowej.","ko-g12-u09.s.5":"Proszę pani, mam pytanie!","ko-g12-u10.title":"W domu","ko-g12-u10.tip":"Koreańczycy zdejmują buty przy drzwiach, zanim wejdą do środka. Podłoga jest często ciepła (ogrzewanie ondol) — przytulnie!","ko-g12-u10.w.0":"dom","ko-g12-u10.w.1":"pokój","ko-g12-u10.w.2":"kuchnia","ko-g12-u10.w.3":"łazienka","ko-g12-u10.w.4":"lampa","ko-g12-u10.w.5":"drzwi","ko-g12-u10.w.6":"kanapa","ko-g12-u10.w.7":"lodówka","ko-g12-u10.w.8":"telewizor","ko-g12-u10.s.0":"Nasz dom jest mały.","ko-g12-u10.s.1":"To mój pokój.","ko-g12-u10.s.2":"Mama jest w kuchni.","ko-g12-u10.s.3":"Włączam światło.","ko-g12-u10.s.4":"Siadam na kanapie.","ko-g12-u10.s.5":"Gdzie jest łazienka?","ko-g12-u11.title":"Ubrania","ko-g12-u11.tip":"Po koreańsku „zakłada się” różne rzeczy różnymi czasownikami: 입어요 ubrania, 신어요 skarpetki i buty, 써요 czapki. Zabawne, prawda?","ko-g12-u11.w.0":"ubrania","ko-g12-u11.w.1":"koszulka","ko-g12-u11.w.2":"spodnie","ko-g12-u11.w.3":"spódnica","ko-g12-u11.w.4":"skarpetki","ko-g12-u11.w.5":"buty","ko-g12-u11.w.6":"czapka","ko-g12-u11.w.7":"rękawiczki","ko-g12-u11.w.8":"piżama","ko-g12-u11.s.0":"Ubieram się.","ko-g12-u11.s.1":"Zakładam skarpetki.","ko-g12-u11.s.2":"Zakładam czapkę.","ko-g12-u11.s.3":"Moje buty są małe.","ko-g12-u11.s.4":"Rękawiczki są ciepłe.","ko-g12-u11.s.5":"Piżama jest ładna.","ko-g12-u12.title":"Pogoda","ko-g12-u12.tip":"Po koreańsku deszcz i śnieg „przychodzą”: 비가 와요, 눈이 와요. W Korei są cztery wyraźne pory roku — którą lubisz?","ko-g12-u12.w.0":"pogoda","ko-g12-u12.w.1":"słońce","ko-g12-u12.w.2":"deszcz","ko-g12-u12.w.3":"śnieg","ko-g12-u12.w.4":"wiatr","ko-g12-u12.w.5":"chmura","ko-g12-u12.w.6":"wiosna","ko-g12-u12.w.7":"lato","ko-g12-u12.w.8":"jesień","ko-g12-u12.w.9":"zima","ko-g12-u12.s.0":"Jest ładna pogoda.","ko-g12-u12.s.1":"Pada deszcz.","ko-g12-u12.s.2":"Pada śnieg.","ko-g12-u12.s.3":"Wieje wiatr.","ko-g12-u12.s.4":"Lato jest gorące.","ko-g12-u12.s.5":"Zima jest zimna.","ko-g12-u12.s.6":"Wiosną kwitną kwiaty.","ko-g12-u13.title":"Dni i czas","ko-g12-u13.tip":"Wszystkie dni tygodnia kończą się na 요일 (dzień tygodnia). 토요일 i 일요일 to weekend — hura!","ko-g12-u13.w.0":"poniedziałek","ko-g12-u13.w.1":"piątek","ko-g12-u13.w.2":"sobota","ko-g12-u13.w.3":"niedziela","ko-g12-u13.w.4":"dzisiaj","ko-g12-u13.w.5":"jutro","ko-g12-u13.w.6":"wczoraj","ko-g12-u13.w.7":"rano","ko-g12-u13.w.8":"noc","ko-g12-u13.s.0":"Dzisiaj jest poniedziałek.","ko-g12-u13.s.1":"Jutro jest sobota.","ko-g12-u13.s.2":"W niedzielę odpoczywam.","ko-g12-u13.s.3":"Rano wstaję.","ko-g12-u13.s.4":"W nocy śpię.","ko-g12-u13.s.5":"Lubię piątki.","ko-g12-u14.title":"W drodze","ko-g12-u14.tip":"Po koreańsku każdym pojazdem „jedzie się” tym samym czasownikiem: 버스를 타요, 자전거를 타요, 비행기를 타요.","ko-g12-u14.w.0":"autobus","ko-g12-u14.w.1":"metro","ko-g12-u14.w.2":"taksówka","ko-g12-u14.w.3":"pociąg","ko-g12-u14.w.4":"samolot","ko-g12-u14.w.5":"rower","ko-g12-u14.w.6":"statek","ko-g12-u14.w.7":"samochód","ko-g12-u14.w.8":"droga","ko-g12-u14.s.0":"Jadę autobusem.","ko-g12-u14.s.1":"Metro jest szybkie.","ko-g12-u14.s.2":"Jeżdżę na rowerze.","ko-g12-u14.s.3":"Samolot leci.","ko-g12-u14.s.4":"Pociąg jest długi.","ko-g12-u14.s.5":"Na drodze jest korek.","ko-g12-u15.title":"Zabawki i zabawa","ko-g12-u15.tip":"W chowanego koreańskie dzieci liczą i wołają 꼭꼭 숨어라, 머리카락 보일라 — „Schowaj się dobrze, widzę twoje włosy!”","ko-g12-u15.w.0":"zabawka","ko-g12-u15.w.1":"lalka","ko-g12-u15.w.2":"klocki","ko-g12-u15.w.3":"piłka","ko-g12-u15.w.4":"hulajnoga","ko-g12-u15.w.5":"puzzle","ko-g12-u15.w.6":"balon","ko-g12-u15.w.7":"gra","ko-g12-u15.w.8":"chowany","ko-g12-u15.s.0":"Pobawmy się razem!","ko-g12-u15.s.1":"Rzucam piłkę.","ko-g12-u15.s.2":"Jeżdżę na hulajnodze.","ko-g12-u15.s.3":"Buduję dom z klocków.","ko-g12-u15.s.4":"Balon odlatuje.","ko-g12-u15.s.5":"Zagrajmy w chowanego.","ko-g12-u16.title":"Przyroda","ko-g12-u16.tip":"Dużą część Korei pokrywają góry, więc wędrówki (등산) to ulubiona weekendowa rozrywka rodzin.","ko-g12-u16.w.0":"góra","ko-g12-u16.w.1":"morze","ko-g12-u16.w.2":"rzeka","ko-g12-u16.w.3":"niebo","ko-g12-u16.w.4":"kwiat","ko-g12-u16.w.5":"drzewo","ko-g12-u16.w.6":"trawa","ko-g12-u16.w.7":"piasek","ko-g12-u16.w.8":"gwiazda","ko-g12-u16.s.0":"Góra jest wysoka.","ko-g12-u16.s.1":"Morze jest szerokie.","ko-g12-u16.s.2":"Niebo jest czyste.","ko-g12-u16.s.3":"Kwiat jest ładny.","ko-g12-u16.s.4":"Drzewo jest duże.","ko-g12-u16.s.5":"Na nocnym niebie jest dużo gwiazd.","ko-g12-u17.title":"Uczucia","ko-g12-u17.tip":"Po koreańsku słowa o uczuciach działają jak czasowniki: 기뻐요 znaczy już „(ja) się cieszę”. Jeśli ktoś wygląda na smutnego, zapytaj 괜찮아요?","ko-g12-u17.w.0":"radosny","ko-g12-u17.w.1":"smutny","ko-g12-u17.w.2":"zły","ko-g12-u17.w.3":"przestraszony","ko-g12-u17.w.4":"zmęczony","ko-g12-u17.w.5":"podekscytowany","ko-g12-u17.w.6":"znudzony","ko-g12-u17.w.7":"w porządku","ko-g12-u17.s.0":"Cieszę się.","ko-g12-u17.s.1":"Mój przyjaciel jest smutny.","ko-g12-u17.s.2":"Padam ze zmęczenia.","ko-g12-u17.s.3":"Dzisiaj jest super ekscytująco!","ko-g12-u17.s.4":"Naprawdę wszystko w porządku?","ko-g12-u17.s.5":"Tak, wszystko w porządku.","ko-g12-u18.title":"Czynności","ko-g12-u18.tip":"Słowa kończące się na 요 są grzeczne. 가요 może znaczyć „idę”, „idziesz” albo „chodźmy” — sytuacja ci podpowie!","ko-g12-u18.w.0":"iść","ko-g12-u18.w.1":"przychodzić","ko-g12-u18.w.2":"jeść","ko-g12-u18.w.3":"pić","ko-g12-u18.w.4":"spać","ko-g12-u18.w.5":"biegać","ko-g12-u18.w.6":"czytać","ko-g12-u18.w.7":"patrzeć","ko-g12-u18.w.8":"siadać","ko-g12-u18.s.0":"Piję wodę.","ko-g12-u18.s.1":"Czytam książkę.","ko-g12-u18.s.2":"Biegnij szybko!","ko-g12-u18.s.3":"Usiądź tutaj.","ko-g12-u18.s.4":"Popatrz na niebo.","ko-g12-u18.s.5":"Idę do domu.","ko-g12-u19.title":"Nasza okolica","ko-g12-u19.tip":"Wiele nazw miejsc kończy się na 원, 관 albo 국 — 병원, 도서관, 우체국. Pochodzą od dawnych chińskich znaków oznaczających budynki.","ko-g12-u19.w.0":"okolica","ko-g12-u19.w.1":"sklep","ko-g12-u19.w.2":"szpital","ko-g12-u19.w.3":"park","ko-g12-u19.w.4":"biblioteka","ko-g12-u19.w.5":"piekarnia","ko-g12-u19.w.6":"poczta","ko-g12-u19.w.7":"plac zabaw","ko-g12-u19.w.8":"komisariat","ko-g12-u19.s.0":"Idę do parku.","ko-g12-u19.s.1":"Piekarnia jest blisko.","ko-g12-u19.s.2":"Czytam książki w bibliotece.","ko-g12-u19.s.3":"Bawię się na placu zabaw.","ko-g12-u19.s.4":"Gdzie jest szpital?","ko-g12-u19.s.5":"Sklep jest duży.","ko-g12-u20.title":"Przyjęcie urodzinowe","ko-g12-u20.tip":"W urodziny Koreańczycy jedzą 미역국 (zupę z wodorostów) — mamy jedzą ją po urodzeniu dziecka, więc ta zupa mówi „dziękuję, mamo”.","ko-g12-u20.w.0":"urodziny","ko-g12-u20.w.1":"przyjęcie","ko-g12-u20.w.2":"prezent","ko-g12-u20.w.3":"tort","ko-g12-u20.w.4":"świeczka","ko-g12-u20.w.5":"piosenka","ko-g12-u20.w.6":"kartka","ko-g12-u20.w.7":"zupa z wodorostów","ko-g12-u20.w.8":"gratulacje","ko-g12-u20.s.0":"Wszystkiego najlepszego z okazji urodzin!","ko-g12-u20.s.1":"Dziękuję za prezent.","ko-g12-u20.s.2":"Tort jest pyszny.","ko-g12-u20.s.3":"Zdmuchuję świeczki.","ko-g12-u20.s.4":"Śpiewamy piosenkę.","ko-g12-u20.s.5":"Jem zupę z wodorostów."},e={"ko-g34-u01.title":"Jestem…: przedstaw się","ko-g34-u01.tip":"Spójrz na ostatni blok słowa: 학생 kończy się na ㅇ, więc mówimy 학생이에요. 의사 nie ma dolnej litery, więc mówimy 의사예요.","ko-g34-u01.w.0":"uczeń","ko-g34-u01.w.1":"lekarz","ko-g34-u01.w.2":"kucharz","ko-g34-u01.w.3":"piosenkarz","ko-g34-u01.w.4":"policjant","ko-g34-u01.w.5":"imię","ko-g34-u01.w.6":"kraj","ko-g34-u01.w.7":"człowiek","ko-g34-u01.w.8":"Korea","ko-g34-u01.w.9":"ja (grzecznie)","ko-g34-u01.s.0":"Jestem uczniem podstawówki.","ko-g34-u01.s.1":"Mam na imię Minjun.","ko-g34-u01.s.2":"Jestem Amerykaninem.","ko-g34-u01.s.3":"Mój tata jest lekarzem.","ko-g34-u01.s.4":"To jest mój przyjaciel.","ko-g34-u01.s.5":"Mam dziesięć lat.","ko-g34-u01.s.6":"Pani nauczycielka jest Koreanką.","ko-g34-u01.s.7":"Miło cię poznać.","ko-g34-u01.g.title":"Mówimy, kim jesteśmy: 이에요 / 예요","ko-g34-u01.g.x.0":"Żeby powiedzieć „A jest B”, postaw 이에요 albo 예요 zaraz po B: 저는 학생이에요 (jestem uczniem).","ko-g34-u01.g.x.1":"Jeśli B kończy się dolną literą (batchim), użyj 이에요: 학생이에요. Jeśli nie, użyj 예요: 의사예요.","ko-g34-u01.g.x.2":"저 znaczy „ja”, kiedy mówisz grzecznie, a 제 znaczy „mój”: 제 이름은 지우예요.","ko-g34-u01.g.0":"Jestem uczniem.","ko-g34-u01.g.1":"Jestem lekarzem.","ko-g34-u01.g.2":"Mam na imię Seoyeon.","ko-g34-u01.g.3":"Jestem piosenkarzem.","ko-g34-u01.g.4":"Jestem Koreańczykiem.","ko-g34-u01.g.5":"Jestem kucharzem.","ko-g34-u01.g.5.task":"Zamień 학생 na 요리사 (kucharz).","ko-g34-u01.g.6":"Moja mama jest policjantką.","ko-g34-u01.g.6.task":"Zamień 의사 na 경찰 (policjant).","ko-g34-u01.g.7":"Mój przyjaciel jest Kanadyjczykiem.","ko-g34-u01.g.7.task":"Zacznij od 제 친구는 (mój przyjaciel).","ko-g34-u01.st.title":"Nowa koleżanka","ko-g34-u01.st.l.0":"Cześć! Jestem Minjun.","ko-g34-u01.st.l.1":"Cześć! Jestem Emma.","ko-g34-u01.st.l.2":"Emma, z jakiego kraju jesteś?","ko-g34-u01.st.l.3":"Jestem Brytyjką.","ko-g34-u01.st.l.4":"Miło cię poznać!","ko-g34-u01.st.l.5":"Mnie też miło.","ko-g34-u01.st.q.0":"Skąd jest Emma?","ko-g34-u01.st.q.0.o.0":"영국","ko-g34-u01.st.q.0.o.1":"한국","ko-g34-u01.st.q.0.o.2":"미국","ko-g34-u01.st.q.1":"Jak ma na imię chłopiec?","ko-g34-u01.st.q.1.o.0":"민준","ko-g34-u01.st.q.1.o.1":"엠마","ko-g34-u01.st.q.1.o.2":"지우","ko-g34-u02.title":"Co to jest?","ko-g34-u02.tip":"Pokazuj palcem, kiedy mówisz! 이거 jest w twojej ręce, 그거 w ręce twojego kolegi, a 저거 daleko od was obu.","ko-g34-u02.w.0":"portfel","ko-g34-u02.w.1":"okulary","ko-g34-u02.w.2":"klucz","ko-g34-u02.w.3":"telefon komórkowy","ko-g34-u02.w.4":"zdjęcie","ko-g34-u02.w.5":"rzecz","ko-g34-u02.w.6":"to (tutaj)","ko-g34-u02.w.7":"to (przy tobie)","ko-g34-u02.w.8":"tamto (daleko)","ko-g34-u02.w.9":"co","ko-g34-u02.s.0":"Co to jest (to przy tobie)?","ko-g34-u02.s.1":"To mój portfel.","ko-g34-u02.s.2":"Czy to (przy tobie) to okulary?","ko-g34-u02.s.3":"Tak, to okulary.","ko-g34-u02.s.4":"Czyje jest tamto?","ko-g34-u02.s.5":"To telefon pani nauczycielki.","ko-g34-u02.s.6":"Te okulary są dziadka.","ko-g34-u02.s.7":"Czyj jest tamten portfel?","ko-g34-u02.g.title":"To, to, tamto: 이 / 그 / 저","ko-g34-u02.g.x.0":"이 = to (blisko mnie), 그 = to (blisko ciebie), 저 = tamto (daleko od nas obu).","ko-g34-u02.g.x.1":"Dodaj 거, żeby powiedzieć „rzecz”: 이거 (ta rzecz), 그거, 저거. Albo dodaj rzeczownik: 이 사진 (to zdjęcie), 저 가방 (tamta torba).","ko-g34-u02.g.x.2":"Pytaj za pomocą 뭐예요: 이거 뭐예요? — Co to jest?","ko-g34-u02.g.0":"Co to jest?","ko-g34-u02.g.1":"Tamto to moja torba.","ko-g34-u02.g.2":"To zdjęcie jest ładne.","ko-g34-u02.g.3":"Daj mi, proszę, ten klucz.","ko-g34-u02.g.4":"To (przy tobie) to mój telefon.","ko-g34-u02.g.5":"To jest ołówek.","ko-g34-u02.g.5.task":"Zamień 그거 na 이거 (to tutaj).","ko-g34-u02.g.6":"Co to jest tam?","ko-g34-u02.g.6.task":"Zapytaj o coś daleko: użyj 저거.","ko-g34-u02.g.7":"Te okulary są ładne.","ko-g34-u02.g.7.task":"Zamień 저 na 이 (ten).","ko-g34-u03.title":"Mam, jest","ko-g34-u03.tip":"Jedno przydatne słowo: samo 없어요 może znaczyć „nie mam” albo „nie ma”. 문제 없어요! = Nie ma problemu!","ko-g34-u03.w.0":"pieniądze","ko-g34-u03.w.1":"czas","ko-g34-u03.w.2":"rodzeństwo","ko-g34-u03.w.3":"zwierzątko domowe","ko-g34-u03.w.4":"problem","ko-g34-u03.w.5":"plany (spotkanie)","ko-g34-u03.w.6":"miejsce (do siedzenia)","ko-g34-u03.w.7":"cukierek","ko-g34-u03.w.8":"przeziębienie","ko-g34-u03.w.9":"bilet","ko-g34-u03.s.0":"Mam młodsze rodzeństwo.","ko-g34-u03.s.1":"W portfelu mam trochę pieniędzy.","ko-g34-u03.s.2":"Masz dziś czas?","ko-g34-u03.s.3":"W domu jest kot.","ko-g34-u03.s.4":"Nie ma problemu.","ko-g34-u03.s.5":"Jutro mam plany.","ko-g34-u03.s.6":"Czy to miejsce jest zajęte?","ko-g34-u03.s.7":"Jest jeden cukierek.","ko-g34-u03.g.title":"Mieć / jest: 있어요 · 없어요","ko-g34-u03.g.x.0":"있어요 znaczy „jest” albo „mam”. 없어요 znaczy „nie ma” albo „nie mam”.","ko-g34-u03.g.x.1":"Po rzeczy postaw 이 albo 가: 이 po dolnej literze (돈이), 가 bez dolnej litery (사과가).","ko-g34-u03.g.x.2":"Pytaj, podnosząc głos na końcu: 시간 있어요? — Masz czas?","ko-g34-u03.g.0":"Nie mam pieniędzy.","ko-g34-u03.g.1":"Jest jabłko.","ko-g34-u03.g.2":"Masz kota?","ko-g34-u03.g.3":"Nie mam czasu.","ko-g34-u03.g.4":"Mam plany.","ko-g34-u03.g.5":"Nie mam rodzeństwa.","ko-g34-u03.g.5.task":"Powiedz „nie mam”: użyj 없어요.","ko-g34-u03.g.6":"Tu jest bilet.","ko-g34-u03.g.6.task":"Zamień 사탕 na 표 (bilet). Uważaj na 이/가!","ko-g34-u03.g.7":"Masz zwierzątko?","ko-g34-u03.g.7.task":"Zamień to na pytanie.","ko-g34-u04.title":"Jeśli chodzi o mnie: 은 / 는","ko-g34-u04.tip":"W Korei dzieci nie mówią do starszego rodzeństwa po imieniu, tylko tymi tytułami. Chłopcy mówią 형 i 누나, a dziewczynki 오빠 i 언니.","ko-g34-u04.w.0":"starszy brat (mówi chłopiec)","ko-g34-u04.w.1":"starszy brat (mówi dziewczynka)","ko-g34-u04.w.2":"starsza siostra (mówi chłopiec)","ko-g34-u04.w.3":"starsza siostra (mówi dziewczynka)","ko-g34-u04.w.4":"wzrost","ko-g34-u04.w.5":"włosy","ko-g34-u04.w.6":"hobby","ko-g34-u04.w.7":"sport, ruch","ko-g34-u04.w.8":"muzyka","ko-g34-u04.w.9":"charakter","ko-g34-u04.s.0":"Mój starszy brat ma dwanaście lat.","ko-g34-u04.s.1":"Moja starsza siostra ma dobry charakter.","ko-g34-u04.s.2":"Jestem niski.","ko-g34-u04.s.3":"Hobby mojej starszej siostry to śpiewanie.","ko-g34-u04.s.4":"Mój starszy brat ma krótkie włosy.","ko-g34-u04.s.5":"Lubię muzykę.","ko-g34-u04.s.6":"Mój starszy brat ćwiczy codziennie.","ko-g34-u04.s.7":"Koty dużo śpią.","ko-g34-u04.g.title":"Mówimy o temacie: 은 / 는","ko-g34-u04.g.x.0":"은/는 pokazuje, o czym mówisz (temat): 저는 학생이에요 — Jeśli chodzi o mnie, jestem uczniem.","ko-g34-u04.g.x.1":"Używaj 은 po dolnej literze (형은) i 는 bez dolnej litery (저는, 누나는).","ko-g34-u04.g.x.2":"Pokazuje też przeciwieństwo: 형은 커요. 저는 작아요. — Mój brat jest wysoki, a ja jestem niski.","ko-g34-u04.g.0":"Jestem Jiwoo.","ko-g34-u04.g.1":"Mój starszy brat jest wysoki.","ko-g34-u04.g.2":"Moja starsza siostra lubi muzykę.","ko-g34-u04.g.3":"Koty są słodkie.","ko-g34-u04.g.4":"Moje hobby to rysowanie.","ko-g34-u04.g.5":"Moja starsza siostra ma długie włosy.","ko-g34-u04.g.5.task":"Powiedz zamiast tego o starszej siostrze (언니).","ko-g34-u04.g.6":"Moje młodsze rodzeństwo jest niskie.","ko-g34-u04.g.6.task":"Zamień 형 na 동생. Uważaj na 은/는!","ko-g34-u04.g.7":"Mój starszy brat jest dobry w sporcie.","ko-g34-u04.g.7.task":"Powiedz o starszym bracie (오빠).","ko-g34-u05.title":"Czasowniki: końcówka 요","ko-g34-u05.tip":"요 na końcu sprawia, że zdanie jest grzeczne. Używaj go z dorosłymi i z osobami, które dopiero poznajesz — z 요 nigdy się nie pomylisz!","ko-g34-u05.w.0":"kupować","ko-g34-u05.w.1":"spotykać","ko-g34-u05.w.2":"uczyć się (do szkoły)","ko-g34-u05.w.3":"bawić się","ko-g34-u05.w.4":"słuchać","ko-g34-u05.w.5":"pisać","ko-g34-u05.w.6":"pracować","ko-g34-u05.w.7":"czekać","ko-g34-u05.w.8":"uczyć się (czegoś nowego)","ko-g34-u05.w.9":"dobry, fajny","ko-g34-u05.s.0":"Uczę się koreańskiego.","ko-g34-u05.s.1":"Spotykam się z kolegą w parku.","ko-g34-u05.s.2":"Kupuję chleb.","ko-g34-u05.s.3":"Młodszy brat się bawi.","ko-g34-u05.s.4":"Słucham muzyki.","ko-g34-u05.s.5":"Mama czeka.","ko-g34-u05.s.6":"Tata pracuje.","ko-g34-u05.s.7":"Pouczmy się razem.","ko-g34-u05.g.title":"Grzeczne końcówki czasowników: -아요 / -어요 / 해요","ko-g34-u05.g.x.0":"Koreańskie czasowniki zmieniają końcówkę. Odejmij 다 i dodaj końcówkę z 요: 가다 → 가요, 먹다 → 먹어요.","ko-g34-u05.g.x.1":"Jeśli ostatnia samogłoska to ㅏ albo ㅗ, dodaj 아요: 놀다 → 놀아요, 보다 → 봐요. Przy innych samogłoskach dodaj 어요: 먹다 → 먹어요.","ko-g34-u05.g.x.2":"Czasowniki na 하다 zmieniają się w 해요: 공부하다 → 공부해요.","ko-g34-u05.g.x.3":"Niektóre samogłoski się łączą: 기다리다 → 기다려요, 마시다 → 마셔요.","ko-g34-u05.g.0":"Spotykam się z kolegą.","ko-g34-u05.g.1":"Jem ryż.","ko-g34-u05.g.2":"Bawię się na placu zabaw.","ko-g34-u05.g.3":"Uczę się koreańskiego.","ko-g34-u05.g.4":"Czytam książkę.","ko-g34-u05.g.5":"Kupuję chleb.","ko-g34-u05.g.5.task":"Zamień 사다 na grzeczną formę z 요.","ko-g34-u05.g.6":"Młodszy brat czeka.","ko-g34-u05.g.6.task":"Zamień 기다리다 na grzeczną formę z 요.","ko-g34-u05.g.7":"Tata pracuje w firmie.","ko-g34-u05.g.7.task":"Zamień 일하다 na grzeczną formę z 요.","ko-g34-u05.st.title":"Co robisz w sobotę?","ko-g34-u05.st.l.0":"Co robisz w sobotę?","ko-g34-u05.st.l.1":"Uczę się pływać.","ko-g34-u05.st.l.2":"Wow! A ja gram w piłkę nożną.","ko-g34-u05.st.l.3":"A w niedzielę?","ko-g34-u05.st.l.4":"Jadę do babci. Jemy razem obiad.","ko-g34-u05.st.l.5":"Fajnie! A ja odpoczywam w domu.","ko-g34-u05.st.q.0":"Czego Seoyeon uczy się w sobotę?","ko-g34-u05.st.q.0.o.0":"수영","ko-g34-u05.st.q.0.o.1":"축구","ko-g34-u05.st.q.0.o.2":"피아노","ko-g34-u05.st.q.1":"Dokąd Minjun jedzie w niedzielę?","ko-g34-u05.st.q.1.o.0":"할머니 집","ko-g34-u05.st.q.1.o.1":"학교","ko-g34-u05.st.q.1.o.2":"공원","ko-g34-u06.title":"Co jesz, oglądasz i robisz: 을 / 를","ko-g34-u06.tip":"Zapamiętaj kolejność: kto → co → robi. 저는 (ja) 피자를 (pizzę) 먹어요 (jem). Słowo o robieniu zawsze stoi na końcu!","ko-g34-u06.w.0":"film","ko-g34-u06.w.1":"obrazek, rysunek","ko-g34-u06.w.2":"list","ko-g34-u06.w.3":"gazeta","ko-g34-u06.w.4":"pianino","ko-g34-u06.w.5":"piłka nożna","ko-g34-u06.w.6":"pływanie","ko-g34-u06.w.7":"sprzątanie","ko-g34-u06.w.8":"zmywanie naczyń","ko-g34-u06.w.9":"kawa","ko-g34-u06.s.0":"Oglądam film z młodszym bratem.","ko-g34-u06.s.1":"Rysuję obrazek.","ko-g34-u06.s.2":"Piszę list do przyjaciela.","ko-g34-u06.s.3":"Gram na pianinie.","ko-g34-u06.s.4":"Gram w piłkę nożną.","ko-g34-u06.s.5":"Tata zmywa naczynia.","ko-g34-u06.s.6":"Mama pije kawę.","ko-g34-u06.s.7":"Sprzątam swój pokój.","ko-g34-u06.g.title":"To, co robisz: 을 / 를","ko-g34-u06.g.x.0":"을/를 oznacza dopełnienie — to, co jesz, oglądasz albo robisz: 사과를 먹어요 (jem jabłko).","ko-g34-u06.g.x.1":"Używaj 을 po dolnej literze (빵을) i 를 bez dolnej litery (커피를).","ko-g34-u06.g.x.2":"W koreańskim czasownik stoi na samym końcu: 저는 영화를 봐요 = ja · film · oglądam.","ko-g34-u06.g.0":"Oglądam film.","ko-g34-u06.g.1":"Jem chleb.","ko-g34-u06.g.2":"Piję kawę.","ko-g34-u06.g.3":"Piszę list.","ko-g34-u06.g.4":"Czytam gazetę.","ko-g34-u06.g.5":"Gram na pianinie.","ko-g34-u06.g.5.task":"Postaw czasownik na końcu.","ko-g34-u06.g.6":"Młodszy brat rysuje obrazek.","ko-g34-u06.g.6.task":"Postaw czasownik na końcu.","ko-g34-u06.g.7":"Mój starszy brat pływa.","ko-g34-u06.g.7.task":"Zamień 축구 (piłka nożna) na 수영 (pływanie).","ko-g34-u07.title":"Nie: 안","ko-g34-u07.tip":"Jeśli nie lubisz ostrego jedzenia, to zdanie przyda ci się w Korei: 안 매운 거 있어요? — Czy jest coś nieostrego?","ko-g34-u07.w.0":"ostry","ko-g34-u07.w.1":"drogi","ko-g34-u07.w.2":"tani","ko-g34-u07.w.3":"trudny","ko-g34-u07.w.4":"łatwy","ko-g34-u07.w.5":"zajęty","ko-g34-u07.w.6":"gorący (o pogodzie)","ko-g34-u07.w.7":"chory, boli","ko-g34-u07.w.8":"pyszny","ko-g34-u07.w.9":"zabawny","ko-g34-u07.s.0":"Tteokbokki jest trochę ostre.","ko-g34-u07.s.1":"To zadanie nie jest łatwe.","ko-g34-u07.s.2":"Ta książka nie jest droga.","ko-g34-u07.s.3":"Tata pije kawę.","ko-g34-u07.s.4":"Praca domowa nie jest trudna.","ko-g34-u07.s.5":"Dzisiaj nie jest gorąco.","ko-g34-u07.s.6":"Już nie boli.","ko-g34-u07.s.7":"Film jest naprawdę zabawny.","ko-g34-u07.g.title":"Nie: 안 + czasownik","ko-g34-u07.g.x.0":"Postaw 안 tuż przed czasownikiem albo słowem opisującym, żeby powiedzieć „nie”: 매워요 → 안 매워요.","ko-g34-u07.g.x.1":"Przy czasownikach z 해요 słowo 안 stoi tuż przed 해요: 공부해요 → 공부 안 해요.","ko-g34-u07.g.x.2":"맛있어요 i 재미있어요 mają własne przeciwieństwa: 맛없어요, 재미없어요.","ko-g34-u07.g.0":"Kimchi nie jest ostre.","ko-g34-u07.g.1":"Nie piję kawy.","ko-g34-u07.g.2":"Dzisiaj nie jestem zajęty.","ko-g34-u07.g.3":"Nie odrabiam pracy domowej.","ko-g34-u07.g.4":"Ta pizza nie jest smaczna.","ko-g34-u07.g.5":"Nie gram na pianinie.","ko-g34-u07.g.5.task":"Zaprzecz z pomocą 안.","ko-g34-u07.g.6":"Dzisiaj nie jest zimno.","ko-g34-u07.g.6.task":"Zaprzecz z pomocą 안.","ko-g34-u07.g.7":"Mój starszy brat nie uprawia sportu.","ko-g34-u07.g.7.task":"Zaprzecz. 안 stoi tuż przed 해요.","ko-g34-u08.title":"Dokąd idziemy: 에 가요","ko-g34-u08.tip":"Busan to duże koreańskie miasto nad morzem, a wyspa Jeju (제주도) to ulubione miejsce rodzinnych wycieczek.","ko-g34-u08.w.0":"targ","ko-g34-u08.w.1":"supermarket","ko-g34-u08.w.2":"basen","ko-g34-u08.w.3":"kino","ko-g34-u08.w.4":"muzeum","ko-g34-u08.w.5":"zoo","ko-g34-u08.w.6":"firma, biuro","ko-g34-u08.w.7":"Seul","ko-g34-u08.w.8":"wycieczka","ko-g34-u08.w.9":"weekend","ko-g34-u08.s.0":"W weekend idę do zoo.","ko-g34-u08.s.1":"Mama idzie na targ.","ko-g34-u08.s.2":"Tata idzie do biura.","ko-g34-u08.s.3":"Latem chodzę na basen.","ko-g34-u08.s.4":"Dokąd jutro idziesz?","ko-g34-u08.s.5":"Idę do muzeum.","ko-g34-u08.s.6":"Jutro jadę do Seulu.","ko-g34-u08.s.7":"Chodźmy razem do kina!","ko-g34-u08.g.title":"Idziemy dokądś: 에 가요 · 에 와요","ko-g34-u08.g.x.0":"Postaw 에 po nazwie miejsca, żeby powiedzieć, dokąd idziesz: 학교에 가요 (idę do szkoły).","ko-g34-u08.g.x.1":"에 się nie zmienia, z dolną literą czy bez: 시장에, 마트에.","ko-g34-u08.g.x.2":"Pytaj z 어디: 어디에 가요? — Dokąd idziesz? Zamiast „iść” możesz powiedzieć „przyjść”, czyli 와요: 집에 와요.","ko-g34-u08.g.0":"Idę do szkoły.","ko-g34-u08.g.1":"Idę do zoo.","ko-g34-u08.g.2":"Dokąd idziesz?","ko-g34-u08.g.3":"Kolega przychodzi do mnie do domu.","ko-g34-u08.g.4":"Idziemy na basen.","ko-g34-u08.g.5":"Jutro idę do muzeum.","ko-g34-u08.g.5.task":"Zamień 극장 (kino) na 박물관 (muzeum).","ko-g34-u08.g.6":"Mama idzie na targ.","ko-g34-u08.g.6.task":"Zamień 마트 na 시장 (targ).","ko-g34-u08.g.7":"Kolega przychodzi do nas do domu.","ko-g34-u08.g.7.task":"Zamień 가요 (iść) na 와요 (przyjść).","ko-g34-u08.st.title":"Plany na weekend","ko-g34-u08.st.l.0":"Dokąd idziesz w weekend?","ko-g34-u08.st.l.1":"Idę do zoo. Są tam pandy!","ko-g34-u08.st.l.2":"Wow, super! Z kim idziesz?","ko-g34-u08.st.l.3":"Z tatą i młodszym bratem. A ty, Jiwoo?","ko-g34-u08.st.l.4":"Jadę do babci. Babcia mieszka w Busanie.","ko-g34-u08.st.l.5":"Morze w Busanie jest piękne!","ko-g34-u08.st.q.0":"Dokąd idzie Hajun?","ko-g34-u08.st.q.0.o.0":"동물원","ko-g34-u08.st.q.0.o.1":"바다","ko-g34-u08.st.q.0.o.2":"시장","ko-g34-u08.st.q.1":"Gdzie mieszka babcia Jiwoo?","ko-g34-u08.st.q.1.o.0":"부산","ko-g34-u08.st.q.1.o.1":"서울","ko-g34-u08.st.q.1.o.2":"제주도","ko-g34-u09.title":"Gdzie to jest?","ko-g34-u09.tip":"Zagraj w chowanego z zabawką: schowaj ją i dawaj wskazówki po koreańsku — 의자 아래에 있어요! 책상 위에 있어요!","ko-g34-u09.w.0":"na, nad","ko-g34-u09.w.1":"pod","ko-g34-u09.w.2":"obok","ko-g34-u09.w.3":"przed","ko-g34-u09.w.4":"za","ko-g34-u09.w.5":"w środku","ko-g34-u09.w.6":"na zewnątrz","ko-g34-u09.w.7":"tutaj","ko-g34-u09.w.8":"tam (przy tobie)","ko-g34-u09.w.9":"tam, daleko","ko-g34-u09.s.0":"Kot jest na łóżku.","ko-g34-u09.s.1":"Kot jest pod kanapą.","ko-g34-u09.s.2":"Ołówek jest w torbie.","ko-g34-u09.s.3":"Przed naszym domem jest park.","ko-g34-u09.s.4":"Mama siada obok mnie.","ko-g34-u09.s.5":"Piesek jest za drzwiami.","ko-g34-u09.s.6":"Łazienka jest tam.","ko-g34-u09.s.7":"Mama jest na dworze.","ko-g34-u09.g.title":"Gdzie coś jest: 에 있어요 · 위 / 아래 / 옆","ko-g34-u09.g.x.0":"Użyj 에 있어요, żeby powiedzieć, gdzie coś jest: 고양이가 방에 있어요 (kot jest w pokoju).","ko-g34-u09.g.x.1":"Żeby wskazać dokładne miejsce, powiedz najpierw rzecz, potem położenie, potem 에: 책상 위에 (na biurku), 의자 아래에 (pod krzesłem).","ko-g34-u09.g.x.2":"Położenie: 위 na, 아래 pod, 옆 obok, 앞 przed, 뒤 za, 안 w środku, 밖 na zewnątrz.","ko-g34-u09.g.0":"Książka jest na biurku.","ko-g34-u09.g.1":"Piłka jest pod krzesłem.","ko-g34-u09.g.2":"Kot jest w pudełku.","ko-g34-u09.g.3":"Kolega jest obok mnie.","ko-g34-u09.g.4":"Za drzewem jest piesek.","ko-g34-u09.g.5":"Mleko jest w lodówce.","ko-g34-u09.g.5.task":"Włóż mleko do lodówki: użyj 안.","ko-g34-u09.g.6":"Park jest przed szkołą.","ko-g34-u09.g.6.task":"Postaw park przed szkołą: użyj 앞.","ko-g34-u09.g.7":"Czy buty są obok drzwi?","ko-g34-u09.g.7.task":"Zamień to na pytanie.","ko-g34-u10.title":"Gdzie coś robisz: 에서","ko-g34-u10.tip":"에 jest do chodzenia gdzieś albo bycia gdzieś (학교에 가요). 에서 jest do robienia czegoś w tym miejscu (학교에서 공부해요).","ko-g34-u10.w.0":"boisko szkolne","ko-g34-u10.w.1":"restauracja","ko-g34-u10.w.2":"kawiarnia","ko-g34-u10.w.3":"plaża","ko-g34-u10.w.4":"sala gimnastyczna","ko-g34-u10.w.5":"koszykówka","ko-g34-u10.w.6":"rysować","ko-g34-u10.w.7":"odpoczywać","ko-g34-u10.w.8":"robić (zdjęcie)","ko-g34-u10.w.9":"śpiewać","ko-g34-u10.s.0":"Bawię się na boisku szkolnym.","ko-g34-u10.s.1":"Jem zimny makaron w restauracji.","ko-g34-u10.s.2":"Czytam książki w bibliotece.","ko-g34-u10.s.3":"Buduję zamek z piasku na plaży.","ko-g34-u10.s.4":"Odpoczywam w domu.","ko-g34-u10.s.5":"Rysuję w parku.","ko-g34-u10.s.6":"Skaczę na skakance w sali gimnastycznej.","ko-g34-u10.s.7":"Gdzie się spotkamy?","ko-g34-u10.g.title":"Gdzie dzieje się czynność: 에서","ko-g34-u10.g.x.0":"Użyj 에서 po miejscu, w którym coś robisz: 식당에서 먹어요 (jem w restauracji).","ko-g34-u10.g.x.1":"Używaj 에 z 가요, 와요 i 있어요: 식당에 가요, 식당에 있어요.","ko-g34-u10.g.x.2":"Szybki test: jeśli ktoś coś tam robi, to jest 에서.","ko-g34-u10.g.0":"Jem w restauracji.","ko-g34-u10.g.1":"Gram w piłkę nożną na boisku szkolnym.","ko-g34-u10.g.2":"Piję sok w kawiarni.","ko-g34-u10.g.3":"Idę do biblioteki.","ko-g34-u10.g.4":"Mój starszy brat jest w swoim pokoju.","ko-g34-u10.g.5":"Robię zdjęcia na plaży.","ko-g34-u10.g.5.task":"Zamień 공원 (park) na 바닷가 (plaża).","ko-g34-u10.g.6":"Bawię się w domu z kolegą.","ko-g34-u10.g.6.task":"Powiedz „bawię się w domu”: użyj 에서 i 놀아요.","ko-g34-u10.g.7":"Gram w koszykówkę w sali gimnastycznej.","ko-g34-u10.g.7.task":"Powiedz, co tam robisz: 농구를 해요 (grać w koszykówkę).","ko-g34-u11.title":"Liczymy rzeczy","ko-g34-u11.tip":"Przy pieniądzach używa się innych liczb (천 = 1000): 삼천 원 to 3000 wonów. Do liczenia rzeczy używa się 한, 두, 세, 네.","ko-g34-u11.w.0":"jeden (przed słowem liczącym)","ko-g34-u11.w.1":"dwa (przed słowem liczącym)","ko-g34-u11.w.2":"trzy (przed słowem liczącym)","ko-g34-u11.w.3":"cztery (przed słowem liczącym)","ko-g34-u11.w.4":"osoby (słowo liczące)","ko-g34-u11.w.5":"zwierzęta (słowo liczące)","ko-g34-u11.w.6":"książki (słowo liczące)","ko-g34-u11.w.7":"kartki (słowo liczące)","ko-g34-u11.w.8":"lata (wiek, słowo liczące)","ko-g34-u11.w.9":"ile","ko-g34-u11.s.0":"Poproszę jedno jabłko.","ko-g34-u11.s.1":"W mojej rodzinie są cztery osoby.","ko-g34-u11.s.2":"Są dwa koty.","ko-g34-u11.s.3":"Ile masz lat?","ko-g34-u11.s.4":"Mam dziewięć lat.","ko-g34-u11.s.5":"Czytam trzy książki.","ko-g34-u11.s.6":"Poproszę kartkę papieru.","ko-g34-u11.s.7":"Jest dziesięciu uczniów.","ko-g34-u11.g.title":"Liczenie: liczba + słowo liczące","ko-g34-u11.g.x.0":"Po koreańsku liczy się ze słowem liczącym po liczbie: 사과 두 개 (dwa jabłka), 학생 세 명 (trzech uczniów).","ko-g34-u11.g.x.1":"하나, 둘, 셋, 넷 skracają się przed słowem liczącym: 한, 두, 세, 네.","ko-g34-u11.g.x.2":"Słowa liczące: 개 rzeczy, 명 osoby, 마리 zwierzęta, 권 książki, 장 kartki papieru, 살 lata (wiek).","ko-g34-u11.g.0":"Poproszę dwa jabłka.","ko-g34-u11.g.1":"Jest trzech uczniów.","ko-g34-u11.g.2":"Jest jeden piesek.","ko-g34-u11.g.3":"Mam osiem lat.","ko-g34-u11.g.4":"Są cztery książki.","ko-g34-u11.g.5":"Są trzy koty.","ko-g34-u11.g.5.task":"Zrób z tego trzy koty.","ko-g34-u11.g.6":"Poproszę dwie kartki papieru.","ko-g34-u11.g.6.task":"Poproś o dwie kartki.","ko-g34-u11.g.7":"Przychodzi czterech kolegów.","ko-g34-u11.g.7.task":"Zrób z tego czterech kolegów.","ko-g34-u11.st.title":"W piekarni","ko-g34-u11.st.l.0":"Dzień dobry! Poproszę dwie bułki.","ko-g34-u11.st.l.1":"Które bułki?","ko-g34-u11.st.l.2":"Jedną z tych bułek z kremem i jedną z tamtych czekoladowych.","ko-g34-u11.st.l.3":"Proszę bardzo. To będzie 3000 wonów.","ko-g34-u11.st.l.4":"Poproszę jeszcze jedno mleko.","ko-g34-u11.st.l.5":"Dobrze, razem 4000 wonów.","ko-g34-u11.st.q.0":"Ile bułek kupuje Seoyeon?","ko-g34-u11.st.q.0.o.0":"두 개","ko-g34-u11.st.q.0.o.1":"세 개","ko-g34-u11.st.q.0.o.2":"한 개","ko-g34-u11.st.q.1":"Co jeszcze kupuje?","ko-g34-u11.st.q.1.o.0":"우유","ko-g34-u11.st.q.1.o.1":"주스","ko-g34-u11.st.q.1.o.2":"케이크","ko-g34-u12.title":"Która godzina?","ko-g34-u12.tip":"Godziny mówi się liczbami 한, 두, 세 (tymi do liczenia), a minuty liczbami 일, 이, 삼 (tymi drugimi). Więc 3:10 to 세 시 십 분.","ko-g34-u12.w.0":"godzina (na zegarze)","ko-g34-u12.w.1":"minuta","ko-g34-u12.w.2":"wpół (trzydzieści minut)","ko-g34-u12.w.3":"teraz","ko-g34-u12.w.4":"przed południem","ko-g34-u12.w.5":"po południu","ko-g34-u12.w.6":"obiad (w południe)","ko-g34-u12.w.7":"wieczór, kolacja","ko-g34-u12.w.8":"wcześnie","ko-g34-u12.w.9":"późno","ko-g34-u12.s.0":"Która jest teraz godzina?","ko-g34-u12.s.1":"Jest pierwsza.","ko-g34-u12.s.2":"Spotkajmy się o wpół do trzeciej.","ko-g34-u12.s.3":"Idę do szkoły o ósmej rano.","ko-g34-u12.s.4":"Jem obiad o pierwszej.","ko-g34-u12.s.5":"Spotkajmy się o czwartej po południu.","ko-g34-u12.s.6":"Wieczorem odrabiam lekcje.","ko-g34-u12.s.7":"Dzisiaj idę spać późno.","ko-g34-u12.g.title":"Mówimy, która godzina: 몇 시예요?","ko-g34-u12.g.x.0":"Godzinę mówisz krótkimi liczbami do liczenia + 시: 한 시, 두 시, 세 시, 열두 시.","ko-g34-u12.g.x.1":"„I pół” to 반: 두 시 반 (2:30). Minuty mówi się drugim zestawem liczb: 오 분, 십 분.","ko-g34-u12.g.x.2":"Dodaj 에, żeby powiedzieć „o”: 일곱 시에 일어나요 (wstaję o siódmej).","ko-g34-u12.g.0":"Jest teraz pierwsza.","ko-g34-u12.g.1":"Jest wpół do czwartej.","ko-g34-u12.g.2":"Wstaję o siódmej.","ko-g34-u12.g.3":"Jem obiad o dwunastej.","ko-g34-u12.g.4":"O której się spotkamy?","ko-g34-u12.g.5":"Wracam do domu o czwartej.","ko-g34-u12.g.5.task":"Zmień godzinę na czwartą.","ko-g34-u12.g.6":"Jest wpół do szóstej.","ko-g34-u12.g.6.task":"Dodaj pół godziny: użyj 반.","ko-g34-u12.g.7":"Idę spać o dziewiątej.","ko-g34-u12.g.7.task":"Powiedz, że idziesz spać o dziewiątej: użyj 에 i 자요.","ko-g34-u13.title":"Kto? Gdzie? Kiedy? Dlaczego?","ko-g34-u13.tip":"Najprzydatniejsze pytanie w koreańskim sklepie: 이거 얼마예요? (Ile to kosztuje?) Spróbuj, bawiąc się w sklep w domu!","ko-g34-u13.w.0":"kto","ko-g34-u13.w.1":"gdzie","ko-g34-u13.w.2":"kiedy","ko-g34-u13.w.3":"dlaczego","ko-g34-u13.w.4":"jak","ko-g34-u13.w.5":"jaki (rodzaj)","ko-g34-u13.w.6":"ile (kosztuje)","ko-g34-u13.w.7":"który","ko-g34-u13.w.8":"powód","ko-g34-u13.w.9":"odpowiedź","ko-g34-u13.s.0":"Kto to jest?","ko-g34-u13.s.1":"Kiedy są wakacje?","ko-g34-u13.s.2":"Dlaczego jesteś smutny?","ko-g34-u13.s.3":"Jak dojść do biblioteki?","ko-g34-u13.s.4":"Ile to kosztuje?","ko-g34-u13.s.5":"Jakie jedzenie lubisz?","ko-g34-u13.s.6":"Z jakiego kraju jesteś?","ko-g34-u13.s.7":"Gdzie jest łazienka?","ko-g34-u13.g.title":"Słowa pytające: 누구, 어디, 언제, 왜, 어떻게, 얼마","ko-g34-u13.g.x.0":"누구 kto · 뭐 co · 어디 gdzie · 언제 kiedy · 왜 dlaczego · 어떻게 jak · 얼마 ile.","ko-g34-u13.g.x.1":"Z 이에요/예요 stoją na końcu: 누구예요? 어디예요? 얼마예요?","ko-g34-u13.g.x.2":"Z innymi czasownikami stoją przed czasownikiem: 어디에 가요? 왜 울어요?","ko-g34-u13.g.0":"Kim jest ta osoba?","ko-g34-u13.g.1":"Kiedy masz urodziny?","ko-g34-u13.g.2":"Dlaczego płaczesz?","ko-g34-u13.g.3":"Ile kosztuje to jabłko?","ko-g34-u13.g.4":"Jak jeździsz do szkoły?","ko-g34-u13.g.5":"Dokąd idziesz?","ko-g34-u13.g.5.task":"Zapytaj „dokąd”: użyj 어디에.","ko-g34-u13.g.6":"Kiedy przyjdziesz?","ko-g34-u13.g.6.task":"Zapytaj „kiedy”: użyj 언제.","ko-g34-u13.g.7":"Kim jest tamta osoba?","ko-g34-u13.g.7.task":"Zapytaj „kto”: użyj 누구예요.","ko-g34-u14.title":"Chcę…","ko-g34-u14.tip":"A co TY chcesz robić? Ułóż trzy zdania z -고 싶어요 o tym weekendzie.","ko-g34-u14.w.0":"marzenie","ko-g34-u14.w.1":"naukowiec","ko-g34-u14.w.2":"malarz","ko-g34-u14.w.3":"sportowiec, zawodnik","ko-g34-u14.w.4":"kosmos","ko-g34-u14.w.5":"wesołe miasteczko","ko-g34-u14.w.6":"tteokbokki (ostre kluski ryżowe)","ko-g34-u14.w.7":"hodować (zwierzę, roślinę)","ko-g34-u14.w.8":"latać","ko-g34-u14.w.9":"bałwan","ko-g34-u14.s.0":"Chcę zostać naukowcem.","ko-g34-u14.s.1":"Chcę polecieć w kosmos.","ko-g34-u14.s.2":"Chcę zjeść tteokbokki.","ko-g34-u14.s.3":"Chcę mieć kota.","ko-g34-u14.s.4":"Chcę pójść do wesołego miasteczka.","ko-g34-u14.s.5":"Co chcesz robić w ten weekend?","ko-g34-u14.s.6":"Dzisiaj chcę odpocząć.","ko-g34-u14.s.7":"Moim marzeniem jest zostać malarzem.","ko-g34-u14.g.title":"Chcę coś zrobić: -고 싶어요","ko-g34-u14.g.x.0":"Żeby powiedzieć, że chcesz coś zrobić, odejmij 다 i dodaj 고 싶어요: 먹다 → 먹고 싶어요 (chcę jeść).","ko-g34-u14.g.x.1":"Działa tak samo z każdym czasownikiem, z dolną literą czy bez: 가고 싶어요, 놀고 싶어요, 쉬고 싶어요.","ko-g34-u14.g.x.2":"„Chcę zostać” to 되고 싶어요: 의사가 되고 싶어요 (chcę zostać lekarzem).","ko-g34-u14.g.0":"Chcę zjeść pizzę.","ko-g34-u14.g.1":"Chcę jechać nad morze.","ko-g34-u14.g.2":"Chcę zostać malarzem.","ko-g34-u14.g.3":"Chcę się bawić z kolegą.","ko-g34-u14.g.4":"Co chcesz robić?","ko-g34-u14.g.5":"Chcę polecieć w kosmos.","ko-g34-u14.g.5.task":"Powiedz, że chcesz: użyj -고 싶어요.","ko-g34-u14.g.6":"Chcę mieć pieska.","ko-g34-u14.g.6.task":"Powiedz, że chcesz: użyj -고 싶어요.","ko-g34-u14.g.7":"Chcę ulepić bałwana.","ko-g34-u14.g.7.task":"Powiedz, że chcesz: użyj -고 싶어요.","ko-g34-u14.st.title":"Moje marzenie","ko-g34-u14.st.l.0":"Dzieci, jakie macie marzenia?","ko-g34-u14.st.l.1":"Ja chcę zostać piłkarzem!","ko-g34-u14.st.l.2":"Ja chcę zostać naukowczynią. Chcę polecieć w kosmos.","ko-g34-u14.st.l.3":"Ja chcę zostać malarką.","ko-g34-u14.st.l.4":"To wszystko wspaniałe marzenia!","ko-g34-u14.st.q.0":"Kim chce zostać Seoyeon?","ko-g34-u14.st.q.0.o.0":"과학자","ko-g34-u14.st.q.0.o.1":"화가","ko-g34-u14.st.q.0.o.2":"축구 선수","ko-g34-u14.st.q.1":"Kto chce zostać malarzem?","ko-g34-u14.st.q.1.o.0":"지우","ko-g34-u14.st.q.1.o.1":"민준","ko-g34-u14.st.q.1.o.2":"서연","ko-g34-u15.title":"Lubię i nie lubię","ko-g34-u15.tip":"Zróbcie z rodziną listę „lubię / nie lubię”: 아빠는 커피를 좋아해요. 저는 벌레를 싫어해요!","ko-g34-u15.w.0":"lubić","ko-g34-u15.w.1":"nie lubić","ko-g34-u15.w.2":"marchewka","ko-g34-u15.w.3":"warzywa","ko-g34-u15.w.4":"papryczka chili","ko-g34-u15.w.5":"czekolada","ko-g34-u15.w.6":"bajka","ko-g34-u15.w.7":"kreskówka, komiks","ko-g34-u15.w.8":"robak","ko-g34-u15.w.9":"najbardziej","ko-g34-u15.s.0":"Lubię czekoladę.","ko-g34-u15.s.1":"Tata lubi marchewkę.","ko-g34-u15.s.2":"Jakie bajki lubisz?","ko-g34-u15.s.3":"Moja starsza siostra boi się robaków.","ko-g34-u15.s.4":"Mój starszy brat lubi bajki.","ko-g34-u15.s.5":"Najbardziej lubię arbuza.","ko-g34-u15.s.6":"Warzywa też lubię.","ko-g34-u15.s.7":"Papryczki chili są za ostre.","ko-g34-u15.g.title":"Lubię i nie lubię: 좋아해요 · 싫어해요","ko-g34-u15.g.x.0":"Używaj 을/를 좋아해요 dla rzeczy, które lubisz: 사과를 좋아해요.","ko-g34-u15.g.x.1":"Używaj 을/를 싫어해요 dla rzeczy, których nie lubisz: 벌레를 싫어해요.","ko-g34-u15.g.x.2":"좋아요 też znaczy „podoba mi się”: 이 노래가 좋아요. Przy 좋아요 używasz 이/가 zamiast 을/를.","ko-g34-u15.g.0":"Lubię koty.","ko-g34-u15.g.1":"Młodszy brat nie znosi marchewki.","ko-g34-u15.g.2":"Lubię czekoladę.","ko-g34-u15.g.3":"Podoba mi się ta piosenka.","ko-g34-u15.g.4":"Jakie kreskówki lubisz?","ko-g34-u15.g.5":"Nie lubię robaków.","ko-g34-u15.g.5.task":"Powiedz, że ich nie lubisz.","ko-g34-u15.g.6":"Mój starszy brat lubi warzywa.","ko-g34-u15.g.6.task":"Zamień 고기 (mięso) na 채소 (warzywa).","ko-g34-u15.g.7":"Najbardziej lubię truskawki.","ko-g34-u15.g.7.task":"Powiedz „najbardziej”: dodaj 제일.","ko-g34-u16.title":"Wczoraj…: czas przeszły","ko-g34-u16.tip":"Posłuchaj dźwięku ㅆ w czasie przeszłym: 갔어요, 봤어요, 했어요. To ㅆ jest jak polskie „-łem” w „zrobiłem”!","ko-g34-u16.w.0":"w zeszłym tygodniu","ko-g34-u16.w.1":"przed chwilą","ko-g34-u16.w.2":"zrobił","ko-g34-u16.w.3":"poszedł","ko-g34-u16.w.4":"zjadł","ko-g34-u16.w.5":"zobaczył, obejrzał","ko-g34-u16.w.6":"przyszedł","ko-g34-u16.w.7":"spał","ko-g34-u16.w.8":"było fajnie","ko-g34-u16.w.9":"wakacje szkolne","ko-g34-u16.s.0":"Wczoraj obejrzałem film.","ko-g34-u16.s.1":"Rano zjadłem chleb.","ko-g34-u16.s.2":"W zeszłym tygodniu pojechałem do Busanu.","ko-g34-u16.s.3":"Odrobiłem całą pracę domową.","ko-g34-u16.s.4":"Kolega przyszedł do mnie do domu.","ko-g34-u16.s.5":"Wczoraj wieczorem wcześnie poszedłem spać.","ko-g34-u16.s.6":"Wakacje były naprawdę fajne.","ko-g34-u16.s.7":"Przed chwilą spotkałem mamę.","ko-g34-u16.g.title":"Czas przeszły: -았어요 / -었어요 / 했어요","ko-g34-u16.g.x.0":"W czasie przeszłym zmienia się końcówka z 요: 가요 → 갔어요, 먹어요 → 먹었어요.","ko-g34-u16.g.x.1":"Czasowniki z ostatnią samogłoską ㅏ albo ㅗ dostają 았어요 (놀다 → 놀았어요, 보다 → 봤어요). Inne dostają 었어요 (먹다 → 먹었어요).","ko-g34-u16.g.x.2":"Czasowniki na 하다 zmieniają się w 했어요: 공부하다 → 공부했어요.","ko-g34-u16.g.0":"Wczoraj poszedłem do parku.","ko-g34-u16.g.1":"Zjadłem śniadanie.","ko-g34-u16.g.2":"Obejrzałem film.","ko-g34-u16.g.3":"Odrobiłem pracę domową.","ko-g34-u16.g.4":"Bawiłem się z kolegą.","ko-g34-u16.g.5":"Przeczytałem książkę.","ko-g34-u16.g.5.task":"Zamień na czas przeszły.","ko-g34-u16.g.6":"Młodszy brat wcześnie poszedł spać.","ko-g34-u16.g.6.task":"Zamień na czas przeszły.","ko-g34-u16.g.7":"Tata ugotował obiad.","ko-g34-u16.g.7.task":"Zamień na czas przeszły.","ko-g34-u16.st.title":"Jak minęły wakacje?","ko-g34-u16.st.l.0":"Udały się wam wakacje?","ko-g34-u16.st.l.1":"Tak! Byłem na wyspie Jeju.","ko-g34-u16.st.l.2":"Wow, co robiłeś na Jeju?","ko-g34-u16.st.l.3":"Pływałem w morzu. Zjadłem też mnóstwo mandarynek.","ko-g34-u16.st.l.4":"A ja byłam u babci. Bawiłam się z pieskiem.","ko-g34-u16.st.l.5":"Wakacje były naprawdę fajne!","ko-g34-u16.st.q.0":"Dokąd pojechał Hajun?","ko-g34-u16.st.q.0.o.0":"제주도","ko-g34-u16.st.q.0.o.1":"서울","ko-g34-u16.st.q.0.o.2":"할머니 집","ko-g34-u16.st.q.1":"Z kim bawiła się Jiwoo?","ko-g34-u16.st.q.1.o.0":"강아지","ko-g34-u16.st.q.1.o.1":"고양이","ko-g34-u16.st.q.1.o.2":"공","ko-g34-u17.title":"Będę…: czas przyszły","ko-g34-u17.tip":"Przeszłość, teraźniejszość, przyszłość: 갔어요 (poszedłem) → 가요 (idę) → 갈 거예요 (pójdę). Powiedz wszystkie trzy dla 먹다 i 하다!","ko-g34-u17.w.0":"w przyszłym tygodniu","ko-g34-u17.w.1":"w przyszłym roku","ko-g34-u17.w.2":"plan","ko-g34-u17.w.3":"sprawdzian","ko-g34-u17.w.4":"biwak","ko-g34-u17.w.5":"namiot","ko-g34-u17.w.6":"ćwiczenie","ko-g34-u17.w.7":"przeprowadzka","ko-g34-u17.w.8":"pewnie, chyba","ko-g34-u17.w.9":"wkrótce","ko-g34-u17.s.0":"Jutro jadę na biwak.","ko-g34-u17.s.1":"W weekend będę ćwiczyć na pianinie.","ko-g34-u17.s.2":"Pewnie będzie padać.","ko-g34-u17.s.3":"W przyszłym tygodniu jest sprawdzian.","ko-g34-u17.s.4":"Będę spać w namiocie.","ko-g34-u17.s.5":"Wkrótce zjemy kolację.","ko-g34-u17.s.6":"W przyszłym roku skończę dziesięć lat.","ko-g34-u17.s.7":"Co będziesz robić w wakacje?","ko-g34-u17.g.title":"Czas przyszły: -(으)ㄹ 거예요","ko-g34-u17.g.x.0":"Żeby mówić o przyszłości, odejmij 다 i dodaj ㄹ 거예요: 가다 → 갈 거예요, 하다 → 할 거예요.","ko-g34-u17.g.x.1":"Jeśli temat kończy się dolną literą, dodaj 을 거예요: 먹다 → 먹을 거예요, 읽다 → 읽을 거예요.","ko-g34-u17.g.x.2":"Może też znaczyć „pewnie”: 비가 올 거예요 (pewnie będzie padać).","ko-g34-u17.g.0":"Jutro pójdę do parku.","ko-g34-u17.g.1":"Na kolację zjem pizzę.","ko-g34-u17.g.2":"W weekend będę się uczyć.","ko-g34-u17.g.3":"Pewnie będzie padać śnieg.","ko-g34-u17.g.4":"Przeczytam książkę.","ko-g34-u17.g.5":"Jutro spotkam się z kolegą.","ko-g34-u17.g.5.task":"Zmień na jutro: użyj 내일 i -ㄹ 거예요.","ko-g34-u17.g.6":"Pojadę na biwak.","ko-g34-u17.g.6.task":"Zamień na czas przyszły.","ko-g34-u17.g.7":"W wakacje nauczę się pływać.","ko-g34-u17.g.7.task":"Zamień na czas przyszły.","ko-g34-u18.title":"I, z, też","ko-g34-u18.tip":"Opowiedz swój poranek jednym długim łańcuszkiem: 일어나고, 씻고, 옷을 입고, 학교에 가요!","ko-g34-u18.w.0":"wstawać","ko-g34-u18.w.1":"myć się","ko-g34-u18.w.2":"zakładać (ubranie)","ko-g34-u18.w.3":"myć zęby","ko-g34-u18.w.4":"sprzątać","ko-g34-u18.w.5":"brać prysznic","ko-g34-u18.w.6":"i (potem)","ko-g34-u18.w.7":"i, z","ko-g34-u18.w.8":"też","ko-g34-u18.w.9":"razem","ko-g34-u18.s.0":"Wstaję i myję twarz.","ko-g34-u18.s.1":"Myję ręce i jem.","ko-g34-u18.s.2":"Biorę mleko i jabłko.","ko-g34-u18.s.3":"Ja też pójdę z wami.","ko-g34-u18.s.4":"Zakładam skarpetki i wychodzę.","ko-g34-u18.s.5":"Sprzątam pokój i odpoczywam.","ko-g34-u18.s.6":"Idę z tatą do parku.","ko-g34-u18.s.7":"Czytam książkę i idę spać.","ko-g34-u18.g.title":"I: -고 · 하고 · 도","ko-g34-u18.g.x.0":"Żeby połączyć dwie czynności, odejmij 다 i dodaj 고: 먹다 → 먹고. 밥을 먹고 양치해요 (jem i myję zęby).","ko-g34-u18.g.x.1":"Żeby połączyć dwa rzeczowniki, użyj 하고: 빵하고 우유 (chleb i mleko). 하고 znaczy też „z”: 엄마하고 가요.","ko-g34-u18.g.x.2":"도 znaczy „też” i stoi zamiast 은/는, 이/가 albo 을/를: 저도 좋아요 (mnie też się podoba).","ko-g34-u18.g.0":"Jem, a potem myję zęby.","ko-g34-u18.g.1":"Ubieram się i idę do szkoły.","ko-g34-u18.g.2":"Jem chleb i piję mleko.","ko-g34-u18.g.3":"Ja też chcę iść.","ko-g34-u18.g.4":"Idę z mamą na targ.","ko-g34-u18.g.5":"Odrabiam lekcje, a potem się bawię.","ko-g34-u18.g.5.task":"Połącz dwa zdania za pomocą -고.","ko-g34-u18.g.6":"Biorę prysznic, a potem idę spać.","ko-g34-u18.g.6.task":"Połącz dwa zdania za pomocą -고.","ko-g34-u18.g.7":"Młodszy brat też przychodzi.","ko-g34-u18.g.7.task":"Powiedz „też”: użyj 도.","ko-g34-u19.title":"Proszę…","ko-g34-u19.tip":"Dwa magiczne zwroty na Koreę: 주세요 (proszę mi dać) i 천천히 말해 주세요 (proszę mówić wolno). Mów je z uśmiechem!","ko-g34-u19.w.0":"proszę mi dać","ko-g34-u19.w.1":"proszę (łagodzi prośbę)","ko-g34-u19.w.2":"proszę usiąść","ko-g34-u19.w.3":"proszę przyjść","ko-g34-u19.w.4":"proszę zaczekać","ko-g34-u19.w.5":"cicho","ko-g34-u19.w.6":"powoli","ko-g34-u19.w.7":"jeszcze raz","ko-g34-u19.w.8":"chwilkę","ko-g34-u19.w.9":"proszę mi pomóc","ko-g34-u19.s.0":"Poproszę szklankę mleka.","ko-g34-u19.s.1":"Proszę usiąść.","ko-g34-u19.s.2":"Witamy, proszę wejść.","ko-g34-u19.s.3":"Proszę tu zaczekać.","ko-g34-u19.s.4":"Proszę trochę wolniej.","ko-g34-u19.s.5":"Proszę powtórzyć jeszcze raz.","ko-g34-u19.s.6":"W bibliotece proszę zachować ciszę.","ko-g34-u19.s.7":"Proszę mi pomóc!","ko-g34-u19.g.title":"Proszę zrobić: -(으)세요 · -아/어 주세요","ko-g34-u19.g.x.0":"Żeby grzecznie poprosić kogoś o zrobienie czegoś, odejmij 다 i dodaj 세요: 가다 → 가세요, 오다 → 오세요.","ko-g34-u19.g.x.1":"Jeśli temat kończy się dolną literą, dodaj 으세요: 앉다 → 앉으세요, 읽다 → 읽으세요.","ko-g34-u19.g.x.2":"Żeby poprosić o przysługę dla siebie, użyj -아/어 주세요: 도와주세요 (proszę mi pomóc), 말해 주세요 (proszę mi powiedzieć).","ko-g34-u19.g.0":"Proszę tu usiąść.","ko-g34-u19.g.1":"Proszę tędy.","ko-g34-u19.g.2":"Proszę przeczytać tę książkę.","ko-g34-u19.g.3":"Proszę mówić wolno.","ko-g34-u19.g.4":"Poproszę wodę.","ko-g34-u19.g.5":"Proszę chwilkę zaczekać.","ko-g34-u19.g.5.task":"Zrób z tego grzeczną prośbę: użyj -세요.","ko-g34-u19.g.6":"Proszę umyć ręce.","ko-g34-u19.g.6.task":"Zrób z tego grzeczną prośbę: użyj -으세요.","ko-g34-u19.g.7":"Proszę powiedzieć to jeszcze raz.","ko-g34-u19.g.7.task":"Poproś o przysługę: użyj 주세요.","ko-g34-u19.st.title":"W restauracji","ko-g34-u19.st.l.0":"Witamy! Ile osób?","ko-g34-u19.st.l.1":"Trzy osoby.","ko-g34-u19.st.l.2":"Proszę tędy. Proszę tu usiąść.","ko-g34-u19.st.l.3":"Poproszę jeden bibimbap i dwa gimbapy.","ko-g34-u19.st.l.4":"Dobrze, proszę chwilkę zaczekać.","ko-g34-u19.st.l.5":"I wodę też poproszę!","ko-g34-u19.st.q.0":"Ile osób jest w rodzinie?","ko-g34-u19.st.q.0.o.0":"세 명","ko-g34-u19.st.q.0.o.1":"두 명","ko-g34-u19.st.q.0.o.2":"네 명","ko-g34-u19.st.q.1":"Co zamawia Seoyeon?","ko-g34-u19.st.q.1.o.0":"비빔밥하고 김밥","ko-g34-u19.st.q.1.o.1":"떡볶이하고 라면","ko-g34-u19.st.q.1.o.2":"김밥 세 개","ko-g34-u20.title":"Bardzo, trochę, za","ko-g34-u20.tip":"Zagrajcie w przeciwieństwa: jedna osoba mówi 커요!, druga odpowiada 작아요! Potem spróbujcie 빨라요 → 느려요.","ko-g34-u20.w.0":"duży","ko-g34-u20.w.1":"mały","ko-g34-u20.w.2":"długi","ko-g34-u20.w.3":"krótki","ko-g34-u20.w.4":"ciężki","ko-g34-u20.w.5":"lekki","ko-g34-u20.w.6":"szybki","ko-g34-u20.w.7":"wolny (powolny)","ko-g34-u20.w.8":"bardzo","ko-g34-u20.w.9":"za (zbyt)","ko-g34-u20.s.0":"Wieloryby są naprawdę duże.","ko-g34-u20.s.1":"Myszy są bardzo małe.","ko-g34-u20.s.2":"Ta książka jest trochę ciężka.","ko-g34-u20.s.3":"Żółwie są bardzo powolne.","ko-g34-u20.s.4":"Pociąg jedzie za szybko.","ko-g34-u20.s.5":"Balony są lekkie.","ko-g34-u20.s.6":"Młodszy brat ma długie włosy.","ko-g34-u20.s.7":"Ten ołówek jest za krótki.","ko-g34-u20.g.title":"Bardzo, trochę, za: 아주 · 조금 · 너무","ko-g34-u20.g.x.0":"Słowa opisujące działają już jak czasowniki: 커요 (jest duży), 빨라요 (jest szybki).","ko-g34-u20.g.x.1":"Postaw 아주 (bardzo), 조금 (trochę) albo 너무 (za) tuż przed nimi: 아주 커요, 조금 작아요, 너무 무거워요.","ko-g34-u20.g.x.2":"Ucz się ich parami: 커요 ↔ 작아요, 길어요 ↔ 짧아요, 빨라요 ↔ 느려요, 무거워요 ↔ 가벼워요.","ko-g34-u20.g.0":"Słonie są bardzo duże.","ko-g34-u20.g.1":"Torba jest za ciężka.","ko-g34-u20.g.2":"Ślimaki są powolne.","ko-g34-u20.g.3":"Moje włosy są trochę krótkie.","ko-g34-u20.g.4":"Gepardy są naprawdę szybkie.","ko-g34-u20.g.5":"Te spodnie są za długie.","ko-g34-u20.g.5.task":"Powiedz „za długie”: dodaj 너무.","ko-g34-u20.g.6":"Mrówki są bardzo małe.","ko-g34-u20.g.6.task":"Powiedz odwrotnie.","ko-g34-u20.g.7":"Pióra są bardzo lekkie.","ko-g34-u20.g.7.task":"Powiedz „bardzo lekkie”: dodaj 아주."},a={"ko-g56-u01.title":"Właśnie teraz: -고 있어요","ko-g56-u01.tip":"Rozejrzyj się i opisz, co wszyscy właśnie robią: 아빠는 요리하고 있어요. 고양이는 자고 있어요.","ko-g56-u01.w.0":"ostatnio","ko-g56-u01.w.1":"gitara","ko-g56-u01.w.2":"rozmowa telefoniczna","ko-g56-u01.w.3":"szykowanie się","ko-g56-u01.w.4":"spacer","ko-g56-u01.w.5":"drzemka","ko-g56-u01.w.6":"pranie","ko-g56-u01.w.7":"SMS","ko-g56-u01.w.8":"wysyłać","ko-g56-u01.w.9":"szukać","ko-g56-u01.w.10":"robić, tworzyć","ko-g56-u01.w.11":"śmiać się, uśmiechać","ko-g56-u01.s.0":"Co teraz robisz?","ko-g56-u01.s.1":"Młodszy brat ucina sobie drzemkę.","ko-g56-u01.s.2":"Mama rozmawia przez telefon.","ko-g56-u01.s.3":"Ostatnio uczę się grać na gitarze.","ko-g56-u01.s.4":"Tata robi pranie.","ko-g56-u01.s.5":"Starszy brat dzwoni do kolegi.","ko-g56-u01.s.6":"Babcia jest na spacerze z pieskiem.","ko-g56-u01.s.7":"Szykuję się do szkoły.","ko-g56-u01.g.title":"Coś dzieje się właśnie teraz: -고 있어요","ko-g56-u01.g.x.0":"Żeby powiedzieć, że coś dzieje się właśnie teraz, odejmij 다 i dodaj 고 있어요: 먹다 → 먹고 있어요 (właśnie jem).","ko-g56-u01.g.x.1":"Działa też dla rzeczy, które robisz ostatnio: 요즘 기타를 배우고 있어요.","ko-g56-u01.g.x.2":"W czasie przeszłym użyj 고 있었어요: 그때 자고 있었어요 (wtedy spałem).","ko-g56-u01.g.0":"Właśnie jem.","ko-g56-u01.g.1":"Dzidziuś ucina sobie drzemkę.","ko-g56-u01.g.2":"Starszy brat gra na gitarze.","ko-g56-u01.g.3":"Co robisz?","ko-g56-u01.g.4":"Wtedy czytałem książkę.","ko-g56-u01.g.5":"Mama właśnie robi pranie.","ko-g56-u01.g.5.task":"Powiedz, że dzieje się to teraz: użyj -고 있어요.","ko-g56-u01.g.6":"Właśnie wysyłam SMS-a do kolegi.","ko-g56-u01.g.6.task":"Powiedz, że dzieje się to teraz: użyj -고 있어요.","ko-g56-u01.g.7":"Ostatnio uczę się pływać.","ko-g56-u01.g.7.task":"Powiedz, że robisz to ostatnio: użyj -고 있어요.","ko-g56-u02.title":"Umiem i nie umiem","ko-g56-u02.tip":"Właśnie czytasz hangul — litery, które stworzył król Sejong, żeby każdy mógł czytać. Super, prawda?","ko-g56-u02.w.0":"hangul (koreański alfabet)","ko-g56-u02.w.1":"litera, znak","ko-g56-u02.w.2":"dźwięk","ko-g56-u02.w.3":"kształt","ko-g56-u02.w.4":"król","ko-g56-u02.w.5":"prosty lud (dawne słowo)","ko-g56-u02.w.6":"łatwo","ko-g56-u02.w.7":"prowadzenie samochodu","ko-g56-u02.w.8":"gwizdanie","ko-g56-u02.w.9":"język obcy","ko-g56-u02.w.10":"stworzył","ko-g56-u02.w.11":"mądry","ko-g56-u02.s.0":"Młodszy brat umie trochę czytać hangul.","ko-g56-u02.s.1":"Młodszy brat jeszcze nie umie jeździć na rowerze.","ko-g56-u02.s.2":"Mama nie umie prowadzić samochodu.","ko-g56-u02.s.3":"Starszy brat dobrze gwiżdże.","ko-g56-u02.s.4":"Pada deszcz, więc nie mogę bawić się na dworze.","ko-g56-u02.s.5":"Starszy brat umie mówić w dwóch językach obcych.","ko-g56-u02.s.6":"Hangulu można się łatwo nauczyć.","ko-g56-u02.s.7":"Ten list łatwo przeczytasz.","ko-g56-u02.g.title":"Mogę i nie mogę: -(으)ㄹ 수 있어요 / 없어요","ko-g56-u02.g.x.0":"Żeby powiedzieć, że coś możesz albo umiesz zrobić, odejmij 다 i dodaj ㄹ 수 있어요: 가다 → 갈 수 있어요, 하다 → 할 수 있어요.","ko-g56-u02.g.x.1":"Po dolnej literze dodaj 을 수 있어요: 읽다 → 읽을 수 있어요. Tematy na ㄹ się nie zmieniają: 놀다 → 놀 수 있어요.","ko-g56-u02.g.x.2":"Żeby powiedzieć „nie mogę”, zamień 있어요 na 없어요: 갈 수 없어요. Możesz też postawić 못 przed czasownikiem: 못 가요.","ko-g56-u02.g.0":"Umiem czytać hangul.","ko-g56-u02.g.1":"Tata umie prowadzić samochód.","ko-g56-u02.g.2":"Dzisiaj nie mogę się bawić.","ko-g56-u02.g.3":"Umiesz gwizdać?","ko-g56-u02.g.4":"Nie umiem pływać.","ko-g56-u02.g.5":"Młodszy brat nie umie jeździć na rowerze.","ko-g56-u02.g.5.task":"Powiedz „nie umie”: użyj 없어요.","ko-g56-u02.g.6":"Starszy brat umie mówić w obcym języku.","ko-g56-u02.g.6.task":"Powiedz, że umie: użyj -ㄹ 수 있어요.","ko-g56-u02.g.7":"Umiesz przeczytać ten list?","ko-g56-u02.g.7.task":"Zapytaj „czy umiesz”: użyj -을 수 있어요.","ko-g56-u02.r.ko":"Tajemnica hangulu","ko-g56-u02.r.genre":"Historia","ko-g56-u02.r.p.0":"Dawno temu Koreańczycy pisali chińskimi znakami. Znaków było bardzo dużo i były trudne. Dlatego wielu zwykłych ludzi nie umiało czytać.","ko-g56-u02.r.p.1":"Król Sejong z Joseonu kochał swój lud. Dlatego w 1443 roku stworzył łatwe litery. Te litery to hangul.","ko-g56-u02.r.p.2":"Spółgłoski powstały z obserwacji kształtu ust i języka przy każdym dźwięku. Na przykład ㄱ pokazuje tylną część języka, która zamyka gardło. Samogłoski powstały z nieba, ziemi i człowieka.","ko-g56-u02.r.p.3":"Za pomocą tylko 24 liter hangulem można zapisać prawie każdy dźwięk. Dlatego każdy może nauczyć się go czytać w kilka dni. 9 października, w Dniu Hangulu, Koreańczycy świętują te litery.","ko-g56-u02.r.q.3.o.0":"zwykli ludzie","ko-g56-u02.r.q.3.o.1":"królowie","ko-g56-u02.r.q.3.o.2":"nauczyciele","ko-g56-u03.title":"Trzeba: -아야 해요","ko-g56-u03.tip":"Koreańskie dzieci uczą się takiej zasady na drodze: przy przejściu dla pieszych zatrzymaj się, popatrz w lewo i w prawo, a przechodząc, podnieś rękę.","ko-g56-u03.w.0":"zasada","ko-g56-u03.w.1":"przestrzegać (zasady)","ko-g56-u03.w.2":"bezpieczeństwo","ko-g56-u03.w.3":"kask","ko-g56-u03.w.4":"przechodzić (na drugą stronę)","ko-g56-u03.w.5":"sygnalizacja świetlna","ko-g56-u03.w.6":"przejście dla pieszych","ko-g56-u03.w.7":"kolejka, rząd","ko-g56-u03.w.8":"kolej (czyja kolej)","ko-g56-u03.w.9":"ważny","ko-g56-u03.w.10":"czysto, dokładnie","ko-g56-u03.w.11":"koniecznie","ko-g56-u03.s.0":"Trzeba dokładnie myć ręce.","ko-g56-u03.s.1":"Trzeba przechodzić po przejściu dla pieszych.","ko-g56-u03.s.2":"Kiedy jeździsz na rowerze, musisz mieć kask.","ko-g56-u03.s.3":"W stołówce stajemy w kolejce.","ko-g56-u03.s.4":"Jutro muszę wcześnie iść do szkoły.","ko-g56-u03.s.5":"Najpierw muszę odrobić lekcje.","ko-g56-u03.s.6":"Wszyscy przestrzegają zasad.","ko-g56-u03.s.7":"Kiedy światło jest zielone, zawsze podnieś rękę i przechodź.","ko-g56-u03.g.title":"Trzeba: -아야 / -어야 해요","ko-g56-u03.g.x.0":"Żeby powiedzieć, że coś trzeba zrobić, weź formę z 요, odejmij 요 i dodaj 야 해요: 가요 → 가야 해요, 먹어요 → 먹어야 해요.","ko-g56-u03.g.x.1":"Czasowniki na 하다 zmieniają się w 해야 해요: 공부해야 해요 (muszę się uczyć).","ko-g56-u03.g.x.2":"W czasie przeszłym powiedz 해야 했어요: 어제 일찍 자야 했어요 (wczoraj musiałem wcześnie iść spać).","ko-g56-u03.g.0":"Trzeba umyć ręce.","ko-g56-u03.g.1":"Muszę już iść.","ko-g56-u03.g.2":"Muszę odrobić lekcje.","ko-g56-u03.g.3":"Trzeba stanąć w kolejce.","ko-g56-u03.g.4":"Trzeba założyć kask.","ko-g56-u03.g.5":"Jutro muszę wcześnie wstać.","ko-g56-u03.g.5.task":"Powiedz, że musisz: użyj -아야 해요.","ko-g56-u03.g.6":"Trzeba przestrzegać zasad szkolnych.","ko-g56-u03.g.6.task":"Powiedz, że trzeba: użyj -어야 해요.","ko-g56-u03.g.7":"Wczoraj musiałem się uczyć.","ko-g56-u03.g.7.task":"Zamień na wczoraj (czas przeszły).","ko-g56-u04.title":"Jeśli, kiedy: -(으)면","ko-g56-u04.tip":"Ułóż zdania z „jeśli” o swoim dniu: 숙제를 다 하면 게임을 해요. 비가 오면 집에서 놀아요.","ko-g56-u04.w.0":"cztery pory roku","ko-g56-u04.w.1":"wyraźny","ko-g56-u04.w.2":"kwiat wiśni","ko-g56-u04.w.3":"pora deszczowa","ko-g56-u04.w.4":"jesienne liście","ko-g56-u04.w.5":"bitwa na śnieżki","ko-g56-u04.w.6":"ciepły","ko-g56-u04.w.7":"chłodny, orzeźwiający","ko-g56-u04.w.8":"jeśli, załóżmy","ko-g56-u04.w.9":"kwitnąć","ko-g56-u04.w.10":"spadać","ko-g56-u04.w.11":"gromadzić się","ko-g56-u04.s.0":"Kiedy napada dużo śniegu, jeździmy na sankach.","ko-g56-u04.s.1":"Jeśli jest ciepło, idę do parku.","ko-g56-u04.s.2":"Kiedy przychodzi lato, zaczyna się pora deszczowa.","ko-g56-u04.s.3":"Jeśli chce ci się pić, napij się wody.","ko-g56-u04.s.4":"Kiedy przychodzi jesień, spadają liście.","ko-g56-u04.s.5":"Jeśli nie ma czasu, zróbmy to jutro.","ko-g56-u04.s.6":"Kiedy wieje chłodny wiatr, idę na spacer.","ko-g56-u04.s.7":"Jeśli pada deszcz, bawimy się w domu.","ko-g56-u04.g.title":"Jeśli, kiedy: -(으)면","ko-g56-u04.g.x.0":"Odejmij 다 i dodaj 면, żeby powiedzieć „jeśli” albo „kiedy”: 오다 → 오면. 비가 오면 우산을 써요 (jeśli pada, biorę parasol).","ko-g56-u04.g.x.1":"Po dolnej literze dodaj 으면: 있다 → 있으면, 먹다 → 먹으면.","ko-g56-u04.g.x.2":"Tematy na ㄹ dostają po prostu 면: 놀다 → 놀면, 만들다 → 만들면.","ko-g56-u04.g.0":"Jeśli pada, biorę parasol.","ko-g56-u04.g.1":"Jeśli masz czas, pobawmy się.","ko-g56-u04.g.2":"Jeśli jesteś głodny, powiedz mi.","ko-g56-u04.g.3":"Jeśli jesteś zmęczony, odpocznij.","ko-g56-u04.g.4":"Jeśli weźmiesz to lekarstwo, poczujesz się lepiej.","ko-g56-u04.g.5":"Kiedy przychodzi wiosna, kwitną wiśnie.","ko-g56-u04.g.5.task":"Połącz je za pomocą -면 (kiedy).","ko-g56-u04.g.6":"Kiedy pada śnieg, bawimy się w bitwę na śnieżki.","ko-g56-u04.g.6.task":"Połącz je za pomocą -면 (kiedy).","ko-g56-u04.g.7":"Jeśli się spóźnię, zadzwonię.","ko-g56-u04.g.7.task":"Połącz je za pomocą -으면 (jeśli).","ko-g56-u04.r.ko":"Cztery pory roku w Korei","ko-g56-u04.r.genre":"Kultura","ko-g56-u04.r.p.0":"Korea ma cztery wyraźne pory roku. Wiosna, lato, jesień i zima bardzo się od siebie różnią. Kiedy przychodzi wiosna, robi się ciepło. Na górach i ulicach kwitną wiśnie i forsycje. Ludzie chodzą do parków oglądać kwiaty.","ko-g56-u04.r.p.1":"Lato jest bardzo gorące. Kiedy przychodzi pora deszczowa, dużo pada. Kiedy pora deszczowa się kończy, dzieci jeżdżą na plażę albo chodzą na basen.","ko-g56-u04.r.p.2":"Jesienią wiatr jest chłodny. Góry robią się piękne od czerwonych i żółtych liści. Zima jest zimna. Kiedy napada dużo śniegu, dzieci lepią bałwany i bawią się w bitwę na śnieżki.","ko-g56-u04.r.q.3.o.0":"kolorowe jesienne liście","ko-g56-u04.r.q.3.o.1":"kwiaty wiśni","ko-g56-u04.r.q.3.o.2":"bałwany","ko-g56-u05.title":"Bo, więc: -아서","ko-g56-u05.tip":"만나서 반가워요 (Miło cię poznać) dosłownie znaczy „Bo się spotkaliśmy, cieszę się” — teraz widzisz w środku -아서!","ko-g56-u05.w.0":"zaspanie","ko-g56-u05.w.1":"spóźnienie (do szkoły)","ko-g56-u05.w.2":"gorączka","ko-g56-u05.w.3":"lekarstwo","ko-g56-u05.w.4":"przewrócić się","ko-g56-u05.w.5":"zranić się","ko-g56-u05.w.6":"śliski","ko-g56-u05.w.7":"miło (cię widzieć)","ko-g56-u05.w.8":"spóźnił się","ko-g56-u05.w.9":"nie zdążyć (na autobus)","ko-g56-u05.w.10":"więc, dlatego","ko-g56-u05.w.11":"bo, ponieważ","ko-g56-u05.s.0":"Przeziębiłem się, więc nie mogłem pójść do szkoły.","ko-g56-u05.s.1":"Spadł śnieg, więc droga jest śliska.","ko-g56-u05.s.2":"Byłem tak śpiący, że uciąłem sobie drzemkę.","ko-g56-u05.s.3":"Byłem spóźniony, więc pojechałem taksówką.","ko-g56-u05.s.4":"Cieszyłem się, że znów zobaczyłem kolegę.","ko-g56-u05.s.5":"Padał deszcz, więc zostałem w domu.","ko-g56-u05.s.6":"Poszedłem do szkoły i spotkałem kolegę.","ko-g56-u05.s.7":"Zraniłem się, więc posmarowałem to maścią.","ko-g56-u05.g.title":"Bo, więc: -아서 / -어서","ko-g56-u05.g.x.0":"Żeby podać powód, weź formę z 요, odejmij 요 i dodaj 서: 고파요 → 고파서. 배가 고파서 먹었어요 (byłem głodny, więc zjadłem).","ko-g56-u05.g.x.1":"Czasowniki na 하다 zmieniają się w 해서: 피곤해서, 공부해서.","ko-g56-u05.g.x.2":"Tylko ostatni czasownik pokazuje przeszłość: 늦잠을 자서 늦었어요 — nigdy 잤어서.","ko-g56-u05.g.x.3":"-아서/어서 łączy też kroki po kolei: 시장에 가서 과일을 샀어요 (poszedłem na targ i kupiłem owoce).","ko-g56-u05.g.0":"Byłem głodny, więc zjadłem chleb.","ko-g56-u05.g.1":"Zaspałem, więc się spóźniłem.","ko-g56-u05.g.2":"Miałem gorączkę, więc poszedłem do szpitala.","ko-g56-u05.g.3":"Byłem tak zmęczony, że wcześnie poszedłem spać.","ko-g56-u05.g.4":"Miło cię poznać.","ko-g56-u05.g.5":"Nie zdążyłem na autobus, więc się spóźniłem.","ko-g56-u05.g.5.task":"Połącz je za pomocą -어서 (więc).","ko-g56-u05.g.6":"Droga była śliska, więc się przewróciłem.","ko-g56-u05.g.6.task":"Połącz je za pomocą -어서 (więc).","ko-g56-u05.g.7":"Poszedłem na targ i kupiłem owoce.","ko-g56-u05.g.7.task":"Połącz kroki za pomocą -아서.","ko-g56-u06.title":"Ale: -지만","ko-g56-u06.tip":"W Księżycowy Nowy Rok dzieci kłaniają się starszym i mówią 새해 복 많이 받으세요 (Dużo szczęścia w nowym roku).","ko-g56-u06.w.0":"Księżycowy Nowy Rok","ko-g56-u06.w.1":"tradycyjne święto","ko-g56-u06.w.2":"Chuseok (święto plonów)","ko-g56-u06.w.3":"noworoczny ukłon","ko-g56-u06.w.4":"noworoczne pieniądze","ko-g56-u06.w.5":"zupa z kluskami ryżowymi","ko-g56-u06.w.6":"hanbok (tradycyjny strój)","ko-g56-u06.w.7":"krewni","ko-g56-u06.w.8":"zbierać się","ko-g56-u06.w.9":"dostawać","ko-g56-u06.w.10":"tradycja","ko-g56-u06.w.11":"ale, jednak","ko-g56-u06.s.0":"Chuseok jest jesienią.","ko-g56-u06.s.1":"Księżycowy Nowy Rok jest pracowity, ale wesoły.","ko-g56-u06.s.2":"Na dworze jest zimno, ale w domu ciepło.","ko-g56-u06.s.3":"Młodszy brat jest mały, ale silny.","ko-g56-u06.s.4":"Jestem najedzony. Ale chcę jeszcze jeść.","ko-g56-u06.s.5":"W Księżycowy Nowy Rok zbierają się krewni.","ko-g56-u06.s.6":"Złożyłem dziadkowi noworoczny ukłon.","ko-g56-u06.s.7":"Dostałem dużo noworocznych pieniędzy.","ko-g56-u06.g.title":"Ale: -지만 · 하지만","ko-g56-u06.g.x.0":"Żeby powiedzieć „ale” w jednym zdaniu, odejmij 다 i dodaj 지만: 맛있다 → 맛있지만. 맛있지만 뜨거워요 (smaczne, ale gorące).","ko-g56-u06.g.x.1":"-지만 działa tak samo z każdym czasownikiem i słowem opisującym: 춥지만, 예쁘지만, 했지만.","ko-g56-u06.g.x.2":"Żeby zacząć nowe zdanie od „ale”, użyj 하지만: 피곤해요. 하지만 행복해요.","ko-g56-u06.g.0":"Zupa z kluskami ryżowymi jest smaczna, ale gorąca.","ko-g56-u06.g.1":"Jest zimno, ale czuję się dobrze.","ko-g56-u06.g.2":"Hanbok jest ładny, ale trochę niewygodny.","ko-g56-u06.g.3":"Młodszy brat jest mały, ale mądry.","ko-g56-u06.g.4":"Jestem zmęczony. Ale jestem szczęśliwy.","ko-g56-u06.g.5":"Nauka jest trudna, ale fajna.","ko-g56-u06.g.5.task":"Zrób z tego jedno zdanie z -지만.","ko-g56-u06.g.6":"Wczoraj padało, ale dzisiaj jest pogodnie.","ko-g56-u06.g.6.task":"Zrób z tego jedno zdanie z -지만.","ko-g56-u06.g.7":"Mój starszy brat jest wysoki, a ja jestem niski.","ko-g56-u06.g.7.task":"Zrób z tego jedno zdanie z -지만.","ko-g56-u06.r.ko":"Noworoczny poranek","ko-g56-u06.r.genre":"Kultura","ko-g56-u06.r.p.0":"Jest noworoczny poranek. Jiwoo wstała wcześnie i założyła hanbok. Hanbok jest ładny, ale trochę niewygodny. Wszyscy krewni zebrali się w domu dziadka.","ko-g56-u06.r.p.1":"Jiwoo złożyła dziadkowi i babci noworoczny ukłon. „Szczęśliwego Nowego Roku!” Dziadek się uśmiechnął i dał jej noworoczne pieniądze.","ko-g56-u06.r.p.2":"Rano wszyscy razem zjedli zupę z kluskami ryżowymi. W Korei mówi się, że po zjedzeniu tej zupy jest się o rok starszym. Po południu Jiwoo grała z kuzynami w yunnori, grę planszową. Przegrała, ale świetnie się bawiła.","ko-g56-u07.title":"Większy, największy","ko-g56-u07.tip":"Porównuj rzeczy dookoła: 아빠가 엄마보다 커요. 고양이가 강아지보다 작아요. Kto w twojej rodzinie jest 제일?","ko-g56-u07.w.0":"niż","ko-g56-u07.w.1":"bardziej","ko-g56-u07.w.2":"mniej","ko-g56-u07.w.3":"najbardziej","ko-g56-u07.w.4":"wysoki","ko-g56-u07.w.5":"niski","ko-g56-u07.w.6":"szeroki, przestronny","ko-g56-u07.w.7":"wąski","ko-g56-u07.w.8":"miasto","ko-g56-u07.w.9":"wieś","ko-g56-u07.w.10":"kuzyn","ko-g56-u07.w.11":"porównanie","ko-g56-u07.s.0":"Tata jest wyższy od mamy.","ko-g56-u07.s.1":"W mieście jest głośniej niż na wsi.","ko-g56-u07.s.2":"To kimchi jest mniej ostre niż tamto.","ko-g56-u07.s.3":"Minjun jest najszybszy w naszej klasie.","ko-g56-u07.s.4":"Góra jest wyższa niż pagórek.","ko-g56-u07.s.5":"Ze wszystkich zwierząt najbardziej lubię koty.","ko-g56-u07.s.6":"Mój pokój jest mniejszy niż pokój młodszego brata.","ko-g56-u07.s.7":"Mój kuzyn jest o rok starszy ode mnie.","ko-g56-u07.g.title":"Porównywanie: 보다 (더) · 제일 / 가장","ko-g56-u07.g.x.0":"Żeby porównać, postaw 보다 po tym, z czym porównujesz: 형이 저보다 커요 (brat jest wyższy ode mnie).","ko-g56-u07.g.x.1":"Możesz dodać 더 (bardziej) albo 덜 (mniej): 서울이 부산보다 더 커요.","ko-g56-u07.g.x.2":"„Naj-” to 제일 albo 가장: 제일 빨라요 (jest najszybszy). Dodaj 에서 dla grupy: 우리 반에서 제일 빨라요.","ko-g56-u07.g.0":"Starszy brat jest wyższy ode mnie.","ko-g56-u07.g.1":"Seul jest większy niż Busan.","ko-g56-u07.g.2":"Dzisiaj jest mniej zimno niż wczoraj.","ko-g56-u07.g.3":"Minjun jest najszybszy.","ko-g56-u07.g.4":"Najbardziej lubię lato.","ko-g56-u07.g.5":"Na wsi jest ciszej niż w mieście.","ko-g56-u07.g.5.task":"Porównaj z miastem: dodaj 도시보다.","ko-g56-u07.g.6":"Ta droga jest szersza niż tamta.","ko-g56-u07.g.6.task":"Porównaj z tamtą drogą: dodaj 저 길보다.","ko-g56-u07.g.7":"Jiwoo jest najwyższa w naszej klasie.","ko-g56-u07.g.7.task":"Powiedz „najwyższa”: dodaj 제일.","ko-g56-u08.title":"Dobre dziecko, ciekawa książka","ko-g56-u08.tip":"Opisz swoje ulubione rzeczy: 제가 좋아하는 색, 제가 좋아하는 동물, 제가 좋아하는 음식은 …","ko-g56-u08.w.0":"nowy","ko-g56-u08.w.1":"stary, używany","ko-g56-u08.w.2":"dawne czasy, dawniej","ko-g56-u08.w.3":"dobry, o dobrym sercu","ko-g56-u08.w.4":"słodki, uroczy","ko-g56-u08.w.5":"sławny","ko-g56-u08.w.6":"cichy","ko-g56-u08.w.7":"hałaśliwy","ko-g56-u08.w.8":"życzliwy","ko-g56-u08.w.9":"nudny","ko-g56-u08.w.10":"taki sam","ko-g56-u08.w.11":"inny","ko-g56-u08.s.0":"Babcia ma uroczego kota.","ko-g56-u08.s.1":"Dobre dziecko pomaga młodszemu rodzeństwu.","ko-g56-u08.s.2":"Czytam w cichej bibliotece.","ko-g56-u08.s.3":"To sławna restauracja.","ko-g56-u08.s.4":"Lubię życzliwych nauczycieli.","ko-g56-u08.s.5":"Kreskówka, którą ogląda starszy brat, jest ciekawa.","ko-g56-u08.s.6":"Mój ulubiony kolor to zielony.","ko-g56-u08.s.7":"Zakładam nowe buty.","ko-g56-u08.g.title":"Opisujemy rzeczownik: -(으)ㄴ / -는","ko-g56-u08.g.x.0":"Żeby postawić słowo opisujące przed rzeczownikiem, odejmij 다 i dodaj ㄴ: 착하다 → 착한 아이 (dobre dziecko), 크다 → 큰 집.","ko-g56-u08.g.x.1":"Po dolnej literze dodaj 은: 작다 → 작은 고양이. Słowa na 있다/없다 dostają 는: 재미있는 책.","ko-g56-u08.g.x.2":"Przy czynnościach, które dzieją się teraz, dodaj 는: 읽다 → 읽는 책 (książka, którą czytam), 좋아하다 → 좋아하는 음식 (ulubione jedzenie).","ko-g56-u08.g.0":"To dobre dziecko.","ko-g56-u08.g.1":"Jest mały kot.","ko-g56-u08.g.2":"Czytam ciekawą książkę.","ko-g56-u08.g.3":"Moje ulubione jedzenie to tteokbokki.","ko-g56-u08.g.4":"Uczę się w cichej bibliotece.","ko-g56-u08.g.5":"Mam uroczego pieska.","ko-g56-u08.g.5.task":"Postaw „uroczy” przed 강아지 w jednym zdaniu.","ko-g56-u08.g.6":"To sławna piosenka.","ko-g56-u08.g.6.task":"Powiedz „sławna piosenka”: postaw 유명한 przed 노래.","ko-g56-u08.g.7":"Książka, którą teraz czytam, jest ciekawa.","ko-g56-u08.g.7.task":"Zrób z tego jedno zdanie: 읽는 책.","ko-g56-u09.title":"Szacunek dla starszych","ko-g56-u09.tip":"Koreańscy dziadkowie często czule nazywają wnuki 우리 강아지 (mój piesku). To słodkie przezwisko!","ko-g56-u09.w.0":"dom (starszej osoby)","ko-g56-u09.w.1":"posiłek (starszej osoby)","ko-g56-u09.w.2":"proszę jeść (do starszej osoby)","ko-g56-u09.w.3":"spać (o starszej osobie)","ko-g56-u09.w.4":"być, przebywać (o starszej osobie)","ko-g56-u09.w.5":"do (starszej osoby)","ko-g56-u09.w.6":"dawać (starszej osobie)","ko-g56-u09.w.7":"wiek (starszej osoby)","ko-g56-u09.w.8":"słowa (starszej osoby)","ko-g56-u09.w.9":"grzeczna mowa","ko-g56-u09.w.10":"dorosły","ko-g56-u09.w.11":"wnuk","ko-g56-u09.s.0":"Dziadku, proszę, weź to.","ko-g56-u09.s.1":"Pani nauczycielka jest w klasie.","ko-g56-u09.s.2":"Dziadek teraz śpi.","ko-g56-u09.s.3":"Dałem babci kwiaty.","ko-g56-u09.s.4":"Dziadek czyta gazetę.","ko-g56-u09.s.5":"Uważnie słucham pani nauczycielki.","ko-g56-u09.s.6":"Do dorosłych mówimy grzecznie.","ko-g56-u09.s.7":"Ile lat ma twój dziadek?","ko-g56-u09.g.title":"Okazujemy szacunek: -(으)세요 · 께 · specjalne słowa","ko-g56-u09.g.x.0":"Kiedy mówisz o starszej osobie, dodaj 시 do czasownika: 가요 → 가세요, 웃어요 → 웃으세요 (babcia się uśmiecha).","ko-g56-u09.g.x.1":"Niektóre słowa zmieniają się całkiem: 먹어요 → 드세요, 자요 → 주무세요, 있어요 → 계세요, 집 → 댁, 나이 → 연세.","ko-g56-u09.g.x.2":"Używaj 께, żeby powiedzieć „do” starszej osoby (할머니께 드려요), i 께서 zamiast 이/가 (할머니께서 웃으세요).","ko-g56-u09.g.0":"Babciu, proszę, jedz.","ko-g56-u09.g.1":"Dziadek jest w swoim pokoju.","ko-g56-u09.g.2":"Dobranoc, babciu.","ko-g56-u09.g.3":"Dałem list pani nauczycielce.","ko-g56-u09.g.4":"Babcia się uśmiecha.","ko-g56-u09.g.5":"Idę do domu dziadka.","ko-g56-u09.g.5.task":"Użyj pełnego szacunku słowa na dom starszej osoby: 댁.","ko-g56-u09.g.6":"Ile lat ma twoja babcia?","ko-g56-u09.g.6.task":"Użyj pełnego szacunku słowa na wiek starszej osoby: 연세.","ko-g56-u09.g.7":"Daję tacie prezent.","ko-g56-u09.g.7.task":"Użyj pełnego szacunku czasownika „dawać” starszej osobie: 드려요.","ko-g56-u09.r.ko":"U babci","ko-g56-u09.r.genre":"Opowiadanie","ko-g56-u09.r.p.0":"W sobotę Hajun pojechał do babci na wieś. Babcia czekała przed drzwiami. „Dzień dobry, babciu!” — głośno przywitał się Hajun.","ko-g56-u09.r.p.1":"Wieczorem babcia ugotowała pyszny gulasz z pasty sojowej. Hajun podał babci łyżkę. „Babciu, proszę, jedz.” Babcia się uśmiechnęła i powiedziała: „Mój wnusio jest najlepszy!”","ko-g56-u09.r.p.2":"W nocy babcia opowiedziała mu dawną historię. Hajun zasnął, słuchając. Babcia przykryła go kocem. „Śpij dobrze, mój piesku.”","ko-g56-u09.r.q.2.o.0":"wnuk","ko-g56-u09.r.q.2.o.1":"babcia","ko-g56-u09.r.q.2.o.2":"sąsiad","ko-g56-u10.title":"Spróbuj!","ko-g56-u10.tip":"Zapytaj rodzinę o ich doświadczenia: 한국 음식을 먹어 봤어요? 태권도를 해 봤어요?","ko-g56-u10.w.0":"doświadczenie","ko-g56-u10.w.1":"pierwszy raz","ko-g56-u10.w.2":"raz","ko-g56-u10.w.3":"smak","ko-g56-u10.w.4":"zapach","ko-g56-u10.w.5":"niesamowity, fascynujący","ko-g56-u10.w.6":"bibimbap","ko-g56-u10.w.7":"taekwondo","ko-g56-u10.w.8":"tradycyjny koreański dom","ko-g56-u10.w.9":"zakładać (buty, skarpetki)","ko-g56-u10.w.10":"jak jest?","ko-g56-u10.w.11":"karuzela (w wesołym miasteczku)","ko-g56-u10.s.0":"Spróbuj też tego kimchi.","ko-g56-u10.s.1":"Jadłeś kiedyś tteokbokki?","ko-g56-u10.s.2":"Tak, raz próbowałem.","ko-g56-u10.s.3":"Przymierz ten kapelusz.","ko-g56-u10.s.4":"Chcę spróbować uczyć się taekwondo.","ko-g56-u10.s.5":"Pierwszy raz spałem w hanoku.","ko-g56-u10.s.6":"Jak smakuje?","ko-g56-u10.s.7":"To było naprawdę niesamowite doświadczenie.","ko-g56-u10.g.title":"Spróbuj: -아/어 보세요 · -아/어 봤어요","ko-g56-u10.g.x.0":"Dodaj 보세요 do formy z -아/어, żeby powiedzieć „spróbuj to zrobić”: 먹어 보세요 (spróbuj zjeść), 입어 보세요 (przymierz).","ko-g56-u10.g.x.1":"봤어요 znaczy, że już tego próbowałeś: 먹어 봤어요 (już to jadłem).","ko-g56-u10.g.x.2":"Pytaj o doświadczenia za pomocą 봤어요?: 한국에 가 봤어요? — Byłeś kiedyś w Korei?","ko-g56-u10.g.0":"Spróbuj tego ciastka ryżowego.","ko-g56-u10.g.1":"Przymierz te ubrania.","ko-g56-u10.g.2":"Jadłeś kiedyś bibimbap?","ko-g56-u10.g.3":"Byłem już w Korei.","ko-g56-u10.g.4":"Spróbuj uczyć się taekwondo.","ko-g56-u10.g.5":"Spałem już w hanoku.","ko-g56-u10.g.5.task":"Powiedz, że masz to doświadczenie: użyj -아 봤어요.","ko-g56-u10.g.6":"Przymierz te buty.","ko-g56-u10.g.6.task":"Zaproś do spróbowania: użyj -어 보세요.","ko-g56-u10.g.7":"Jechałeś kiedyś tą karuzelą?","ko-g56-u10.g.7.task":"Zapytaj o doświadczenie: użyj -아 봤어요?","ko-g56-u11.title":"Może…?","ko-g56-u11.tip":"W Korei można zamówić jedzenie z dostawą prawie wszędzie — nawet do parku nad rzeką!","ko-g56-u11.w.0":"piknik, wycieczka","ko-g56-u11.w.1":"drugie śniadanie (na wynos)","ko-g56-u11.w.2":"koc piknikowy","ko-g56-u11.w.3":"smażony kurczak","ko-g56-u11.w.4":"dostawa","ko-g56-u11.w.5":"rzeka Han","ko-g56-u11.w.6":"puszczać (latawiec)","ko-g56-u11.w.7":"pożyczać, wypożyczać","ko-g56-u11.w.8":"zamawiać (jedzenie)","ko-g56-u11.w.9":"wspólnie","ko-g56-u11.w.10":"krajobraz, widok","ko-g56-u11.w.11":"zachód słońca","ko-g56-u11.s.0":"Może pójdziemy jutro do parku?","ko-g56-u11.s.1":"O której się spotkamy?","ko-g56-u11.s.2":"Może zamówimy pizzę?","ko-g56-u11.s.3":"Może puścimy razem latawiec?","ko-g56-u11.s.4":"Może rozłożymy koc tutaj?","ko-g56-u11.s.5":"Puszczamy latawce nad rzeką Han.","ko-g56-u11.s.6":"Zachód słońca jest naprawdę piękny.","ko-g56-u11.s.7":"Co dzisiaj zjemy?","ko-g56-u11.g.title":"Może…?: -(으)ㄹ까요?","ko-g56-u11.g.x.0":"Żeby zaproponować wspólne zrobienie czegoś, odejmij 다 i dodaj ㄹ까요?: 가다 → 갈까요? (Może pójdziemy?)","ko-g56-u11.g.x.1":"Po dolnej literze dodaj 을까요?: 먹다 → 먹을까요?, 앉다 → 앉을까요?","ko-g56-u11.g.x.2":"Odpowiedz 네, 좋아요! albo zaproponuj coś innego formą z 요: 공원에 가요! (Chodźmy do parku!)","ko-g56-u11.g.0":"Może pojedziemy w weekend na piknik?","ko-g56-u11.g.1":"Co zjemy?","ko-g56-u11.g.2":"Gdzie się spotkamy?","ko-g56-u11.g.3":"Może pojeździmy razem na rowerach?","ko-g56-u11.g.4":"Może usiądziemy tutaj?","ko-g56-u11.g.5":"Może zamówimy smażonego kurczaka?","ko-g56-u11.g.5.task":"Zrób z tego propozycję: użyj -을까요?","ko-g56-u11.g.6":"Może puścimy latawce nad rzeką Han?","ko-g56-u11.g.6.task":"Zrób z tego propozycję: użyj -ㄹ까요?","ko-g56-u11.g.7":"Może pójdziemy dziś razem do biblioteki?","ko-g56-u11.g.7.task":"Zrób z tego propozycję: użyj -ㄹ까요?","ko-g56-u11.r.ko":"Piknik nad rzeką Han","ko-g56-u11.r.genre":"Pamiętnik","ko-g56-u11.r.p.0":"Niedziela, 3 października. Pogoda była piękna. Cała rodzina pojechała na piknik nad rzekę Han. Mama przygotowała nam pudełka z gimbapem.","ko-g56-u11.r.p.1":"Tata zapytał: „Może wypożyczymy rowery i pojeździmy?” Jeździliśmy na rowerach wzdłuż rzeki. Wiatr był chłodny, więc czułem się naprawdę dobrze.","ko-g56-u11.r.p.2":"W porze obiadu rozłożyliśmy koc i zjedliśmy nasze jedzenie. Młodszy brat powiedział, że chce też kurczaka. Więc zamówiliśmy kurczaka z dostawą. To niesamowite, że jedzenie dowożą nawet nad rzekę Han.","ko-g56-u11.r.p.3":"Wieczorem puszczaliśmy latawce i oglądaliśmy zachód słońca. Niebo zrobiło się czerwone i było bardzo piękne. Chcę tu wrócić w następny weekend.","ko-g56-u11.r.q.3.o.0":"czerwone niebo o zachodzie słońca","ko-g56-u11.r.q.3.o.1":"latawiec","ko-g56-u11.r.q.3.o.2":"koc piknikowy","ko-g56-u12.title":"Proszę nie…","ko-g56-u12.tip":"W Korei zobaczysz -지 마세요 na tabliczkach: 만지지 마세요 (Nie dotykać), 들어가지 마세요 (Nie wchodzić).","ko-g56-u12.w.0":"hałasować, gadać","ko-g56-u12.w.1":"dotykać","ko-g56-u12.w.2":"wyrzucać","ko-g56-u12.w.3":"śmieci","ko-g56-u12.w.4":"niebezpieczny","ko-g56-u12.w.5":"martwić się","ko-g56-u12.w.6":"psota, figiel","ko-g56-u12.w.7":"galeria sztuki","ko-g56-u12.w.8":"dzieło sztuki","ko-g56-u12.w.9":"filmowanie, robienie zdjęć","ko-g56-u12.w.10":"jedzenie (i picie)","ko-g56-u12.w.11":"spieszyć się","ko-g56-u12.s.0":"Nie hałasuj w bibliotece.","ko-g56-u12.s.1":"Nie dotykaj obrazu.","ko-g56-u12.s.2":"Nie wyrzucaj śmieci na ulicę.","ko-g56-u12.s.3":"Nie martw się za bardzo.","ko-g56-u12.s.4":"Nie biegaj po jezdni. To niebezpieczne.","ko-g56-u12.s.5":"Nie spiesz się na schodach.","ko-g56-u12.s.6":"W galerii sztuki nie rób zdjęć.","ko-g56-u12.s.7":"Nie rób kolegom psikusów.","ko-g56-u12.g.title":"Proszę nie: -지 마세요","ko-g56-u12.g.x.0":"Żeby grzecznie poprosić kogoś, żeby czegoś nie robił, odejmij 다 i dodaj 지 마세요: 만지다 → 만지지 마세요 (proszę nie dotykać).","ko-g56-u12.g.x.1":"Działa tak samo z każdym czasownikiem: 먹지 마세요, 뛰지 마세요, 걱정하지 마세요.","ko-g56-u12.g.x.2":"Do bliskiego kolegi możesz powiedzieć -지 마: 울지 마! (Nie płacz!)","ko-g56-u12.g.0":"Proszę nie dotykać dzieła sztuki.","ko-g56-u12.g.1":"Proszę się nie martwić.","ko-g56-u12.g.2":"Proszę nie hałasować w klasie.","ko-g56-u12.g.3":"Proszę nie biegać po jezdni.","ko-g56-u12.g.4":"Proszę tu nie jeść.","ko-g56-u12.g.5":"Proszę nie śmiecić.","ko-g56-u12.g.5.task":"Powiedz „proszę nie”: użyj -지 마세요.","ko-g56-u12.g.6":"Proszę nie robić zdjęć w galerii sztuki.","ko-g56-u12.g.6.task":"Powiedz „proszę nie”: użyj -지 마세요.","ko-g56-u12.g.7":"Proszę się nie spieszyć.","ko-g56-u12.g.7.task":"Powiedz „proszę nie”: użyj -지 마세요.","ko-g56-u13.title":"Przed i po","ko-g56-u13.tip":"Zróbcie z rodziną gimbap (albo coś prostego) i mów każdy krok po koreańsku: 먼저 …, 그다음에 …, 마지막으로 …","ko-g56-u13.w.0":"składniki","ko-g56-u13.w.1":"suszone wodorosty","ko-g56-u13.w.2":"rozkładać","ko-g56-u13.w.3":"zwijać","ko-g56-u13.w.4":"kroić w plasterki","ko-g56-u13.w.5":"nóż","ko-g56-u13.w.6":"mieszać","ko-g56-u13.w.7":"olej sezamowy","ko-g56-u13.w.8":"szynka","ko-g56-u13.w.9":"marynowana żółta rzodkiew","ko-g56-u13.w.10":"ostatni","ko-g56-u13.w.11":"uważać","ko-g56-u13.s.0":"Przed snem czytam książkę.","ko-g56-u13.s.1":"Po sprzątaniu jem przekąskę.","ko-g56-u13.s.2":"Przed wyjściem do szkoły jem śniadanie.","ko-g56-u13.s.3":"Po pływaniu biorę prysznic.","ko-g56-u13.s.4":"Przed gotowaniem myję składniki.","ko-g56-u13.s.5":"Rozłóż ryż na wodorostach.","ko-g56-u13.s.6":"Uważaj, kiedy używasz noża.","ko-g56-u13.s.7":"Na koniec pokrój gimbap w plasterki.","ko-g56-u13.g.title":"Przed i po: -기 전에 · -(으)ㄴ 후에","ko-g56-u13.g.x.0":"„Przed zrobieniem”: odejmij 다 i dodaj 기 전에: 먹다 → 먹기 전에 (przed jedzeniem).","ko-g56-u13.g.x.1":"„Po zrobieniu”: odejmij 다 i dodaj ㄴ 후에: 하다 → 한 후에. Po dolnej literze dodaj 은 후에: 먹다 → 먹은 후에.","ko-g56-u13.g.x.2":"Przy rzeczownikach dodaj po prostu 전에 albo 후에: 수업 전에, 방학 후에.","ko-g56-u13.g.0":"Przed jedzeniem myję ręce.","ko-g56-u13.g.1":"Po odrobieniu lekcji się bawię.","ko-g56-u13.g.2":"Przed snem myję zęby.","ko-g56-u13.g.3":"Po jedzeniu idę na spacer.","ko-g56-u13.g.4":"Po szkole idę na taekwondo.","ko-g56-u13.g.5":"Zanim zrobimy gimbap, przygotowujemy składniki.","ko-g56-u13.g.5.task":"Użyj -기 전에, żeby zrobić jedno zdanie.","ko-g56-u13.g.6":"Po obejrzeniu filmu jemy.","ko-g56-u13.g.6.task":"Użyj -ㄴ 후에, żeby zrobić jedno zdanie.","ko-g56-u13.g.7":"Po prysznicu zakładam piżamę.","ko-g56-u13.g.7.task":"Użyj -ㄴ 후에, żeby zrobić jedno zdanie.","ko-g56-u13.r.ko":"Zróbmy gimbap","ko-g56-u13.r.genre":"Przepis","ko-g56-u13.r.p.0":"Gimbap to jedzenie, które Koreańczycy często zabierają na pikniki. Dziś zrobię gimbap z mamą. Zanim zaczniemy, dokładnie myję ręce.","ko-g56-u13.r.p.1":"Najpierw przygotuj składniki. Potrzebne są wodorosty, ryż, jajko, szynka, marynowana rzodkiew i szpinak. Dodaj do ryżu sól i olej sezamowy i wymieszaj. Mama kroi szynkę i jajko nożem w długie paski. Noże są niebezpieczne, więc powinien ich używać dorosły.","ko-g56-u13.r.p.2":"Rozłóż cienko ryż na wodorostach. Połóż na wierzchu nadzienie i ciasno zwiń. Na koniec mama pokroiła mi gimbap w plasterki. Gimbap, który zrobiłem, był naprawdę pyszny!","ko-g56-u14.title":"Rozmowa z przyjaciółmi","ko-g56-u14.tip":"W Korei 반말 używa się tylko wtedy, gdy jest się blisko i w podobnym wieku. Jeśli nie masz pewności, zostaw 요 — to zawsze bezpieczne.","ko-g56-u14.w.0":"mowa potoczna","ko-g56-u14.w.1":"być blisko (przyjaźnić się)","ko-g56-u14.w.2":"no (potoczne „tak”)","ko-g56-u14.w.3":"nie no (potoczne „nie”)","ko-g56-u14.w.4":"dzięki (potocznie)","ko-g56-u14.w.5":"sorki (potocznie)","ko-g56-u14.w.6":"spoko (potocznie)","ko-g56-u14.w.7":"co robisz? (potocznie)","ko-g56-u14.w.8":"pobawmy się","ko-g56-u14.w.9":"serio (potocznie)","ko-g56-u14.w.10":"relacja","ko-g56-u14.w.11":"rówieśnik","ko-g56-u14.s.0":"Jesteśmy w tym samym wieku?","ko-g56-u14.s.1":"No, ja też mam dziesięć lat.","ko-g56-u14.s.2":"Co dziś robisz?","ko-g56-u14.s.3":"Chodźmy do mnie!","ko-g56-u14.s.4":"Sorki za wcześniej.","ko-g56-u14.s.5":"Spoko, nie martw się.","ko-g56-u14.s.6":"Ta piosenka jest serio dobra!","ko-g56-u14.s.7":"Do nauczycielki mówimy grzecznie.","ko-g56-u14.g.title":"Mowa potoczna z przyjaciółmi: bez 요","ko-g56-u14.g.x.0":"Z bliskimi przyjaciółmi i młodszymi dziećmi Koreańczycy używają 반말 (mowy potocznej). Najczęściej po prostu odejmujesz 요: 가요 → 가, 먹어요 → 먹어.","ko-g56-u14.g.x.1":"이에요/예요 zmieniają się w 이야/야: 학생이에요 → 학생이야, 친구예요 → 친구야.","ko-g56-u14.g.x.2":"„Chodźmy…!” do kolegi to -자: 가자! 먹자! 놀자! A 네 → 응, 아니요 → 아니.","ko-g56-u14.g.x.3":"Do dorosłych, nauczycieli i osób, które dopiero poznajesz, zawsze mów z 요!","ko-g56-u14.g.0":"Co teraz robisz?","ko-g56-u14.g.1":"Ja też mam dziesięć lat.","ko-g56-u14.g.2":"To mój przyjaciel.","ko-g56-u14.g.3":"Zjedzmy razem!","ko-g56-u14.g.4":"Sorki, że się spóźniłem.","ko-g56-u14.g.5":"Pobawmy się razem!","ko-g56-u14.g.5.task":"Powiedz to bliskiemu koledze: użyj -자.","ko-g56-u14.g.6":"Ta gra jest serio fajna!","ko-g56-u14.g.6.task":"Powiedz to bliskiemu koledze: odejmij 요 i użyj 진짜.","ko-g56-u14.g.7":"Jestem uczniem.","ko-g56-u14.g.7.task":"Powiedz to w 반말: 저는 → 나는, 이에요 → 이야.","ko-g56-u15.title":"Kiedy…: -(으)ㄹ 때","ko-g56-u15.tip":"Mów o uczuciach z -ㄹ 때: 기쁠 때 노래해요. 슬플 때 엄마를 안아요. A co ty robisz, kiedy się nudzisz?","ko-g56-u15.w.0":"śpiący","ko-g56-u15.w.1":"spragniony","ko-g56-u15.w.2":"ciekawy","ko-g56-u15.w.3":"urażony","ko-g56-u15.w.4":"samotny","ko-g56-u15.w.5":"ciężki, trudny","ko-g56-u15.w.6":"pocieszać","ko-g56-u15.w.7":"sam","ko-g56-u15.w.8":"myśl","ko-g56-u15.w.9":"wspomnienie","ko-g56-u15.w.10":"kiedy byłem mały","ko-g56-u15.w.11":"karaoke (salka)","ko-g56-u15.s.0":"Kiedy się nudzę, rysuję.","ko-g56-u15.s.1":"Kiedy jestem głodny, jem jabłko.","ko-g56-u15.s.2":"Kiedy jestem czegoś ciekawy, pytam nauczycielkę.","ko-g56-u15.s.3":"Kiedy kolega jest urażony, pocieszam go.","ko-g56-u15.s.4":"Kiedy jestem sam, czytam książki.","ko-g56-u15.s.5":"Kiedy byłem mały, mieszkałem na wsi.","ko-g56-u15.s.6":"Kiedy jest mi ciężko, myślę o przyjacielu.","ko-g56-u15.s.7":"Kiedy idę na karaoke, jestem podekscytowany.","ko-g56-u15.g.title":"Kiedy: -(으)ㄹ 때","ko-g56-u15.g.x.0":"Żeby powiedzieć „kiedy (coś się dzieje)”, odejmij 다 i dodaj ㄹ 때: 졸리다 → 졸릴 때 (kiedy chce mi się spać).","ko-g56-u15.g.x.1":"Po dolnej literze dodaj 을 때: 먹다 → 먹을 때, 있다 → 있을 때.","ko-g56-u15.g.x.2":"W czasie przeszłym użyj 았/었을 때: 어렸을 때 (kiedy byłem mały). Przy rzeczownikach dodaj po prostu 때: 방학 때, 점심 때.","ko-g56-u15.g.0":"Kiedy chce mi się spać, myję twarz.","ko-g56-u15.g.1":"Nie rozmawiaj, kiedy jesz.","ko-g56-u15.g.2":"Kiedy jestem sam, słucham muzyki.","ko-g56-u15.g.3":"Kiedy jesteś czegoś ciekawy, pytaj.","ko-g56-u15.g.4":"W wakacje jeżdżę do babci.","ko-g56-u15.g.5":"Kiedy chce mi się pić, piję wodę.","ko-g56-u15.g.5.task":"Użyj -ㄹ 때, żeby zrobić jedno zdanie.","ko-g56-u15.g.6":"Kiedy jestem urażony, mama mnie pociesza.","ko-g56-u15.g.6.task":"Użyj -ㄹ 때, żeby zrobić jedno zdanie.","ko-g56-u15.g.7":"Kiedy byłem mały, mieszkałem na wsi.","ko-g56-u15.g.7.task":"Użyj -았/었을 때, żeby zrobić jedno zdanie.","ko-g56-u16.title":"Opowiadamy historię","ko-g56-u16.tip":"Heungbu i Nolbu to jedna z najbardziej znanych koreańskich baśni ludowych. Opowiedz ją rodzinie, używając 먼저, 그다음에, 그런데 i 마지막으로!","ko-g56-u16.w.0":"najpierw","ko-g56-u16.w.1":"potem","ko-g56-u16.w.2":"ale, a wtedy","ko-g56-u16.w.3":"nagle","ko-g56-u16.w.4":"na koniec","ko-g56-u16.w.5":"chciwość","ko-g56-u16.w.6":"biedny","ko-g56-u16.w.7":"bogacz","ko-g56-u16.w.8":"jaskółka","ko-g56-u16.w.9":"nasiono","ko-g56-u16.w.10":"tykwa","ko-g56-u16.w.11":"skarb","ko-g56-u16.s.0":"Najpierw odrabiam lekcje.","ko-g56-u16.s.1":"Potem bawię się z pieskiem.","ko-g56-u16.s.2":"Na koniec piszę w pamiętniku.","ko-g56-u16.s.3":"Pojechaliśmy na piknik. Ale zapomnieliśmy jedzenia.","ko-g56-u16.s.4":"Nagle przybiegł piesek.","ko-g56-u16.s.5":"Boli mnie brzuch. Więc idę do szpitala.","ko-g56-u16.s.6":"Nolbu był bardzo chciwy.","ko-g56-u16.s.7":"Z tykwy wyszedł skarb.","ko-g56-u16.g.title":"Opowiadamy po kolei: 먼저, 그다음에, 그래서, 그런데","ko-g56-u16.g.x.0":"Stawiaj te słowa na początku zdania, żeby opowiadać po kolei: 먼저 (najpierw) → 그다음에 (potem) → 마지막으로 (na koniec).","ko-g56-u16.g.x.1":"그래서 znaczy „więc” (skutek): 비가 와요. 그래서 집에 있어요.","ko-g56-u16.g.x.2":"그런데 znaczy „ale” albo „a wtedy” (coś niespodziewanego): 공원에 갔어요. 그런데 문이 닫혀 있었어요.","ko-g56-u16.g.x.3":"갑자기 znaczy „nagle”: 갑자기 불이 꺼졌어요.","ko-g56-u16.g.0":"Najpierw umyj ręce.","ko-g56-u16.g.1":"Potem jedz.","ko-g56-u16.g.2":"Pada deszcz. Więc biorę parasol.","ko-g56-u16.g.3":"Poszedłem do parku. A wtedy zaczęło padać.","ko-g56-u16.g.4":"Na koniec umyj zęby.","ko-g56-u16.g.5":"Byłem głodny. Więc zjadłem chleb.","ko-g56-u16.g.5.task":"Podziel to na dwa zdania z 그래서.","ko-g56-u16.g.6":"Szedłem. Nagle zaczęło padać.","ko-g56-u16.g.6.task":"Dodaj „nagle”: użyj 갑자기.","ko-g56-u16.g.7":"Najpierw odrabiam lekcje. Potem się bawię.","ko-g56-u16.g.7.task":"Opowiedz to w dwóch krokach: 먼저 … 그다음에 …","ko-g56-u16.r.ko":"Heungbu i Nolbu","ko-g56-u16.r.genre":"Baśń ludowa","ko-g56-u16.r.p.0":"Dawno, dawno temu żyło dwóch braci: Heungbu i Nolbu. Starszy brat, Nolbu, był bogaty, ale bardzo chciwy. Młodszy brat, Heungbu, był biedny, ale miał dobre serce.","ko-g56-u16.r.p.1":"Pewnego wiosennego dnia Heungbu zobaczył jaskółkę ze zranioną nóżką. Ostrożnie opatrzył jej nóżkę. Kiedy przyszła jesień, jaskółka odleciała na ciepłe południe.","ko-g56-u16.r.p.2":"Następnej wiosny jaskółka wróciła z nasionem tykwy. Kiedy Heungbu je zasadził, wyrosły ogromne tykwy. Kiedy rozciął jedną z nich, wysypało się z niej złoto i skarby!","ko-g56-u16.r.p.3":"Kiedy Nolbu usłyszał tę historię, specjalnie zranił jaskółce nóżkę. Ale z tykw Nolbu wyskoczyły chochliki i go ukarały. W końcu Nolbu pożałował tego, co zrobił, i stał się dobrym człowiekiem.","ko-g56-u16.r.q.3.o.0":"chciwość","ko-g56-u16.r.q.3.o.1":"dobroć","ko-g56-u16.r.q.3.o.2":"skarb"},u={"tier.first.label":"Pierwsze słowa","tier.first.age":"Nawet bez umiejętności czytania","tier.first.desc":"Posłuchaj słowa, dotknij obrazka · czytanie niepotrzebne","tier.kinder.label":"Hangul","tier.kinder.age":"Zacznij tu, jeśli dopiero zaczynasz","tier.kinder.desc":"Koreańskie litery i ich łączenie · powitania, liczby, kolory","tier.g12.label":"Pierwsze zdania","tier.g12.age":"Jeśli czytasz hangul","tier.g12.desc":"Jedzenie, ciało, szkoła, pogoda · krótkie zdania","tier.g34.label":"Podstawy gramatyki","tier.g34.age":"Jeśli znasz krótkie zdania","tier.g34.desc":"Partykuły, końcówki czasowników, przeszłość i przyszłość · dialogi","tier.g56.label":"Czytanie","tier.g56.age":"Jeśli umiesz budować zdania","tier.g56.desc":"Móc, musieć, grzeczna mowa · krótkie teksty"},g={...u,...o,...i,...k,...e,...a};export{g as default};
